css:
@property --fxs-marbling-spread {
  syntax: '<length>';
  inherits: false;
  initial-value: 0px;
}
.fxs-marbling {
  /* Re-theme with these four. Everything else is derived. */
  --fxs-marbling-paper: oklch(0.958 0.017 86);
  --fxs-marbling-sumi: oklch(0.26 0.018 265);
  --fxs-marbling-bengara: oklch(0.54 0.14 34);
  --fxs-marbling-ai: oklch(0.43 0.1 252);

  --fxs-marbling-wash: color-mix(in oklch, var(--fxs-marbling-ai) 30%, var(--fxs-marbling-paper));
  --fxs-marbling-text: color-mix(in oklch, var(--fxs-marbling-sumi) 94%, var(--fxs-marbling-paper));
  --fxs-marbling-muted: color-mix(in oklch, var(--fxs-marbling-sumi) 58%, var(--fxs-marbling-paper));
  --fxs-marbling-chip: color-mix(in oklch, var(--fxs-marbling-paper) 86%, transparent);
  --fxs-marbling-rule: color-mix(in oklch, var(--fxs-marbling-sumi) 16%, transparent);
  --fxs-marbling-focus: var(--fxs-marbling-bengara);
  --fxs-marbling-out: cubic-bezier(.16, 1, .3, 1);
  --fxs-marbling-spring: linear(0, 0.061, 0.212, 0.395, 0.582, 0.755, 0.892, 0.995, 1.061, 1.097, 1.110, 1.105, 1.091, 1.070, 1.050, 1.031, 1.014, 1.003, 0.994, 0.990, 0.988, 0.988, 0.990, 0.992, 0.994, 0.996, 0.998, 1.000, 1.000, 1.001, 1.001, 1.001, 1.001, 1.001, 1.001, 1.000, 1);

  container-type: inline-size;
  position: relative;
  inline-size: 100%;
  aspect-ratio: 5 / 4;
  min-block-size: 200px;
  max-block-size: 380px;
  border-radius: 16px;
  overflow: hidden;
  isolation: isolate;
  background: var(--fxs-marbling-paper);
  color: var(--fxs-marbling-text);
  font-family: system-ui, sans-serif;
  box-shadow: inset 0 0 0 1px var(--fxs-marbling-rule);

  & .fxs-marbling__gl,
  & .fxs-marbling__fallback,
  & .fxs-marbling__surface {
    position: absolute;
    inset: 0;
    inline-size: 100%;
    block-size: 100%;
  }
  & .fxs-marbling__gl { display: block; }
  & .fxs-marbling__surface {
    z-index: 1;
    cursor: crosshair;
    touch-action: pan-y;
    border-radius: inherit;
    outline: none;
  }
  & .fxs-marbling__surface:focus-visible {
    box-shadow: inset 0 0 0 2px var(--fxs-marbling-focus), inset 0 0 0 5px color-mix(in oklch, var(--fxs-marbling-focus) 22%, transparent);
  }
  & .fxs-marbling__stylus {
    --px: 0;
    --py: 0;
    position: absolute;
    z-index: 2;
    left: 0;
    top: 0;
    inline-size: 22px;
    aspect-ratio: 1;
    translate: calc(var(--px) * 1px - 50%) calc(var(--py) * 1px - 50%);
    border-radius: 50%;
    border: 1.5px solid var(--fxs-marbling-focus);
    background: radial-gradient(circle, var(--fxs-marbling-focus) 0 2px, transparent 2.5px);
    opacity: 0;
    scale: .6;
    pointer-events: none;
    transition: opacity .2s, scale .45s var(--fxs-marbling-spring), translate .32s var(--fxs-marbling-out);
  }
  &:has(.fxs-marbling__surface:focus-visible) .fxs-marbling__stylus { opacity: 1; scale: 1; }

  & .fxs-marbling__ui {
    position: absolute;
    inset: 0;
    z-index: 3;
    display: grid;
    grid-template-columns: 1fr auto;
    grid-template-rows: auto 1fr auto;
    grid-template-areas: "head count" "hint hint" "bar bar";
    padding: clamp(10px, 4cqi, 18px);
    pointer-events: none;
  }
  & .fxs-marbling__head { grid-area: head; display: grid; gap: 2px; justify-items: start; }
  & .fxs-marbling__eyebrow {
    font: 600 clamp(9px, 2.4cqi, 10.5px)/1.2 ui-monospace, Menlo, monospace;
    letter-spacing: .14em;
    text-transform: uppercase;
    color: var(--fxs-marbling-muted);
    text-shadow: 0 0 8px var(--fxs-marbling-paper), 0 0 2px var(--fxs-marbling-paper);
  }
  & .fxs-marbling__title {
    margin: 0;
    font-size: clamp(20px, 7.4cqi, 30px);
    font-weight: 680;
    letter-spacing: -.03em;
    line-height: 1;
    text-wrap: balance;
    text-shadow: 0 0 14px var(--fxs-marbling-paper), 0 0 3px var(--fxs-marbling-paper);
  }
  & .fxs-marbling__hint {
    grid-area: hint;
    place-self: end center;
    margin: 0 0 8px;
    padding: 6px 12px;
    border-radius: 99px;
    background: var(--fxs-marbling-chip);
    font-size: clamp(11px, 3.1cqi, 12.5px);
    font-weight: 520;
    text-wrap: pretty;
    box-shadow: 0 0 0 1px var(--fxs-marbling-rule);
    transition: opacity .5s var(--fxs-marbling-out), translate .6s var(--fxs-marbling-out);
  }
  & .fxs-marbling__ui[data-used] .fxs-marbling__hint { opacity: 0; translate: 0 8px; }

  & .fxs-marbling__bar {
    grid-area: bar;
    display: grid;
    grid-template-columns: auto 1fr auto;
    grid-template-areas: "inks . rinse";
    align-items: center;
    gap: 8px;
    padding: 5px;
    border-radius: 14px;
    background: var(--fxs-marbling-chip);
    box-shadow: 0 0 0 1px var(--fxs-marbling-rule), 0 8px 24px -16px color-mix(in oklch, var(--fxs-marbling-sumi) 60%, transparent);
    backdrop-filter: blur(6px) saturate(1.2);
  }
  & .fxs-marbling__inks { grid-area: inks; display: flex; gap: 2px; }
  & .fxs-marbling__ink,
  & .fxs-marbling__rinse {
    pointer-events: auto;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    block-size: 30px;
    padding: 0 9px 0 7px;
    border: 0;
    border-radius: 10px;
    background: transparent;
    color: inherit;
    font: 560 12px/1 system-ui, sans-serif;
    cursor: pointer;
  }
  /* Entry: staggered by --i. Only opacity/translate wait; hover and press respond at once. */
  & .fxs-marbling__ink,
  & .fxs-marbling__count,
  & .fxs-marbling__rinse {
    transition:
      opacity .6s var(--fxs-marbling-out) calc(var(--i, 0) * 45ms + 120ms),
      translate .6s var(--fxs-marbling-out) calc(var(--i, 0) * 45ms + 120ms),
      background-color .2s,
      scale .45s var(--fxs-marbling-spring);
    @starting-style { opacity: 0; translate: 0 6px; }
  }
  & .fxs-marbling__ink:hover,
  & .fxs-marbling__rinse:hover { background: color-mix(in oklch, var(--fxs-marbling-sumi) 7%, transparent); }
  & .fxs-marbling__ink:active,
  & .fxs-marbling__rinse:active { scale: .94; }
  & .fxs-marbling__ink:focus-visible,
  & .fxs-marbling__rinse:focus-visible { outline: 2px solid var(--fxs-marbling-focus); outline-offset: 1px; }
  & .fxs-marbling__ink[aria-checked="true"] {
    background: color-mix(in oklch, var(--fxs-marbling-sumi) 10%, var(--fxs-marbling-paper));
  }
  & .fxs-marbling__dot {
    inline-size: 14px;
    aspect-ratio: 1;
    border-radius: 50%;
    background: var(--c);
    box-shadow: 0 0 0 1.5px var(--fxs-marbling-paper), 0 0 0 2.5px transparent;
    transition: box-shadow .3s var(--fxs-marbling-out), scale .5s var(--fxs-marbling-spring);
  }
  & .fxs-marbling__ink[data-ink="0"] { --c: var(--fxs-marbling-sumi); }
  & .fxs-marbling__ink[data-ink="1"] { --c: var(--fxs-marbling-bengara); }
  & .fxs-marbling__ink[data-ink="2"] { --c: var(--fxs-marbling-ai); }
  & .fxs-marbling__ink[aria-checked="true"] .fxs-marbling__dot {
    box-shadow: 0 0 0 1.5px var(--fxs-marbling-paper), 0 0 0 3px var(--c);
    scale: 1.08;
  }
  & .fxs-marbling__count {
    grid-area: count;
    align-self: start;
    display: grid;
    justify-items: end;
    gap: 3px;
    padding: 6px 8px;
    border-radius: 9px;
    background: var(--fxs-marbling-chip);
    box-shadow: 0 0 0 1px var(--fxs-marbling-rule);
    font: 500 10.5px/1 ui-monospace, Menlo, monospace;
    color: var(--fxs-marbling-muted);
    white-space: nowrap;
    font-variant-numeric: tabular-nums;
    & b { color: var(--fxs-marbling-text); font-weight: 650; display: inline-block; }
    & i { font-style: normal; display: inline-block; min-inline-size: 7ch; text-align: start; }
    & b.is-bump { animation: fxs-marbling-bump .5s var(--fxs-marbling-spring); }
  }
  & .fxs-marbling__rinse {
    grid-area: rinse;
    padding-inline: 8px 10px;
    & svg { inline-size: 14px; block-size: 14px; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
    &:hover svg { rotate: -40deg; }
    & svg { transition: rotate .5s var(--fxs-marbling-spring); }
  }
  & .fxs-marbling__sr { position: absolute; inline-size: 1px; block-size: 1px; overflow: hidden;
    clip-path: inset(50%); white-space: nowrap; }

  /* No WebGL: two floated drops as concentric gradient rings, slowly spreading. */
  & .fxs-marbling__fallback {
    display: none;
    &::before,
    &::after {
      content: "";
      position: absolute;
      border-radius: 50%;
      animation: fxs-marbling-spread 9s var(--fxs-marbling-out) infinite alternate;
    }
    &::before {
      inset: 30% auto auto 14%;
      inline-size: 40%;
      aspect-ratio: 1;
      background: repeating-radial-gradient(circle, var(--fxs-marbling-sumi) 0 calc(5px + var(--fxs-marbling-spread)), var(--fxs-marbling-paper) 0 calc(9px + var(--fxs-marbling-spread)), var(--fxs-marbling-ai) 0 calc(13px + var(--fxs-marbling-spread)), var(--fxs-marbling-paper) 0 calc(17px + var(--fxs-marbling-spread)));
    }
    &::after {
      inset: 40% 12% auto auto;
      inline-size: 28%;
      aspect-ratio: 1;
      background: repeating-radial-gradient(circle, var(--fxs-marbling-bengara) 0 6px, var(--fxs-marbling-paper) 0 10px);
      animation-delay: -4s;
    }
  }
  &[data-render="fallback"] .fxs-marbling__fallback { display: block; }
  &[data-render="fallback"] .fxs-marbling__gl,
  &[data-render="fallback"] .fxs-marbling__count,
  &[data-render="fallback"] .fxs-marbling__hint,
  &[data-render="fallback"] .fxs-marbling__bar { display: none; }
}
@keyframes fxs-marbling-bump {
  0% { scale: 1; }
  30% { scale: 1.35; color: var(--fxs-marbling-bengara); }
  100% { scale: 1; }
}
@keyframes fxs-marbling-spread {
  to { --fxs-marbling-spread: 6px; }
}
@container (inline-size < 330px) {
  .fxs-marbling .fxs-marbling__name { display: none; }
  .fxs-marbling .fxs-marbling__ink { padding-inline: 8px; }
}
@container (inline-size < 270px) {
  .fxs-marbling .fxs-marbling__rinse span { display: none; }
  .fxs-marbling .fxs-marbling__count { display: none; }
}
@media (prefers-reduced-motion: reduce) {
  .fxs-marbling {
    & .fxs-marbling__fallback { animation: none; }
    & .fxs-marbling__stylus,
    & .fxs-marbling__hint,
    & .fxs-marbling__ink,
    & .fxs-marbling__count,
    & .fxs-marbling__rinse,
    & .fxs-marbling__rinse svg,
    & .fxs-marbling__dot { transition: opacity .2s linear; }
    & .fxs-marbling__count b.is-bump { animation: none; }
  }
}

