const FRAG = `#extension GL_OES_standard_derivatives : enable
#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif
uniform vec2 uRes;
uniform float uTime;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * .1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}
float vnoise(vec2 p) {
  vec2 i = floor(p), f = fract(p);
  vec2 w = f * f * (3. - 2. * f);
  return mix(mix(hash12(i), hash12(i + vec2(1., 0.)), w.x),
             mix(hash12(i + vec2(0., 1.)), hash12(i + vec2(1., 1.)), w.x), w.y);
}
const mat2 OCT = mat2(.8, .6, -.6, .8);
float fbm(vec2 p) {
  float a = .5, s = 0.;
  for (int i = 0; i < 5; i++) { s += a * vnoise(p); p = OCT * p * 2.03; a *= .5; }
  return s;
}

uniform vec3 uPaper, uSumi, uBengara, uAi, uWash;
uniform vec4 uOp[8];      /* drop: xy centre, z radius, w ink · stroke: xy point, z -alpha, w angle */
uniform vec2 uPtr, uDrag;
uniform float uPx;

vec3 inkOf(float k) { return k < .5 ? uSumi : (k < 1.5 ? uBengara : uAi); }

/* The undisturbed tray: domain-warped fbm (a warp of a warp) cut into thin ink lines.
   Three octaves only: suminagashi lines are long and smooth, never speckled. */
float fbm3(vec2 p) {
  float a = .5, s = 0.;
  for (int i = 0; i < 3; i++) { s += a * vnoise(p); p = OCT * p * 2.03; a *= .5; }
  return s / .875;
}
vec3 tray(vec2 p) {
  float t = uTime * .025;
  vec2 q = p * .95;
  vec2 a = vec2(fbm3(q + vec2(0., t)), fbm3(q + vec2(5.2, 1.3 - t)));
  vec2 b = vec2(fbm3(q + 2.6 * a + vec2(1.7, 9.2) + t * .7), fbm3(q + 2.6 * a + vec2(8.3, 2.8) - t * .4));
  float v = fbm3(q + 2.4 * b);
  float x = v * 7.;
  float f = fract(x), id = mod(floor(x), 3.);
  float aa = fwidth(x) * 1.1 + 1e-4;
  float line = smoothstep(0., aa, f) * (1. - smoothstep(.1 - aa, .1 + aa, f));
  vec3 ink = id < .5 ? uSumi : (id < 1.5 ? uWash : uAi);
  vec3 col = mix(uPaper, uWash, smoothstep(.45, .95, v) * .22);
  return mix(col, ink, line * (.18 + .42 * smoothstep(.3, .9, length(b))));
}

void main() {
  vec2 p = (gl_FragCoord.xy - .5 * uRes) / uRes.y;
  vec2 s = p;
  vec2 dp = s - uPtr;
  s -= uDrag * exp(-dot(dp, dp) / .018);          /* a finger's wake, relaxes back */
  vec3 acc = vec3(0.);
  float rem = 1.;
  /* Undo every operation, newest first. Drops use Jaffer's area-preserving map
     P = C + (P'-C)·sqrt(1 - r²/|P'-C|²); strokes are tine lines P = P' - αλ/(d+λ)·M. */
  for (int i = 7; i >= 0; i--) {
    vec4 o = uOp[i];
    if (o.z > .0005) {
      vec2 v = s - o.xy;
      float l2 = dot(v, v), r2 = o.z * o.z;
      float aa = 3. * o.z * uPx;
      float inside = 1. - smoothstep(r2 - aa, r2 + aa, l2);
      if (inside > 0.) {
        float k = l2 / r2 * 3.;
        float f = fract(k);
        float wk = max(6. * sqrt(l2) * uPx / r2, 1e-4) * 1.3;
        float m = 1. - smoothstep(.62 - wk, .62 + wk, f);
        m = max(m, smoothstep(1. - wk, 1., f));
        vec3 ink = inkOf(o.w) * (.82 + .18 * smoothstep(0., .6, f));
        acc += rem * inside * mix(uPaper, ink, m);
        rem *= 1. - inside;
      }
      s = o.xy + v * sqrt(max(0., 1. - r2 / max(l2, r2)));
    } else if (o.z < -.0005) {
      vec2 M = vec2(cos(o.w), sin(o.w));
      float d = abs(dot(s - o.xy, vec2(-M.y, M.x)));
      s -= (-o.z) * .05 / (d + .05) * M;
    }
  }
  vec3 col = acc + rem * tray(s);
  col *= 1. - .03 * vnoise(p * vec2(380., 70.)) - .02 * vnoise(p * vec2(60., 260.));
  vec2 vg = p * vec2(.8, 1.);
  col *= 1. - .08 * dot(vg, vg);
  col += (hash12(gl_FragCoord.xy) - .5) / 255.;
  gl_FragColor = vec4(col, 1.);
}
`;
const T0 = 6;
const MAX = 8;
const INKS = ['Sumi', 'Bengara', 'Ai'];
const ui = root.querySelector('.fxs-marbling__ui');
const surface = root.querySelector('.fxs-marbling__surface');
const stylus = root.querySelector('.fxs-marbling__stylus');
const live = root.querySelector('.fxs-marbling__sr');
const counts = { drops: root.querySelector('[data-k="drops"]'), strokes: root.querySelector('[data-k="strokes"]') };
const inkBtns = [...root.querySelectorAll('.fxs-marbling__ink')];
const ops = [];                        /* oldest first, at most MAX */
const opBuf = new Float32Array(32);
const pal = {};
const ptr = [0, 0], drag = [0, 0], dragT = [0, 0], cursor = [0, 0];
let ink = 0, idle = 0, clock = 0, gesture = null, lastMove = null, shown = { drops: -1, strokes: -1 };
/* Opening composition: three drops and a comb stroke, staggered. */
const intro = [
  { at: .2, op: { kind: 'drop', x: -.22, y: .06, ink: 0, to: .2 } },
  { at: .75, op: { kind: 'drop', x: .26, y: -.08, ink: 1, to: .15 } },
  { at: 1.3, op: { kind: 'drop', x: -.02, y: -.02, ink: 2, to: .12 } },
  { at: 2.2, op: { kind: 'stroke', x: 0, y: .02, angle: -.35, to: .16 } },
];

/* ── shader host ───────────────────────────────────────────────────────────
   One full-screen triangle. DPR-aware sizing (capped), adaptive resolution
   when frames run long, paused off screen and in hidden tabs, theme colours
   resolved from the root's custom properties, and the WebGL context released
   as soon as the component leaves the document. */
const canvas = root.querySelector('.fxs-marbling__gl');
const probe = root.querySelector('.fxs-marbling__probe');
const motionQ = matchMedia('(prefers-reduced-motion: reduce)');
let calm = motionQ.matches;
const swatch = Object.assign(document.createElement('canvas'), { width: 1, height: 1 })
  .getContext('2d', { willReadFrequently: true });
/* Resolve a custom property (oklch, color-mix, var chains…) to linear-free sRGB 0..1. */
function rgb(prop) {
  probe.style.color = 'var(' + prop + ')';
  swatch.clearRect(0, 0, 1, 1);
  swatch.fillStyle = '#000';
  swatch.fillStyle = getComputedStyle(probe).color;
  swatch.fillRect(0, 0, 1, 1);
  const d = swatch.getImageData(0, 0, 1, 1).data;
  return [d[0] / 255, d[1] / 255, d[2] / 255];
}
let gl = null, prog = null, dead = false, raf = 0, last = 0, t = T0;
let onScreen = true, scale = 1, ema = 1 / 60, frames = 0, w = 300, h = 150;
const U = {};
try {
  gl = canvas.getContext('webgl', { alpha: false, antialias: false, depth: false, stencil: false,
    premultipliedAlpha: false, powerPreference: 'low-power' });
} catch (e) { gl = null; }
if (gl) { gl.getExtension('OES_standard_derivatives'); prog = link(FRAG); }
if (!prog) degrade();
function link(fs) {
  const mk = (type, src) => {
    const s = gl.createShader(type);
    gl.shaderSource(s, src);
    gl.compileShader(s);
    if (gl.getShaderParameter(s, gl.COMPILE_STATUS)) return s;
    console.warn('[fxs-marbling] shader', gl.getShaderInfoLog(s));
    return null;
  };
  const v = mk(gl.VERTEX_SHADER, 'attribute vec2 p;void main(){gl_Position=vec4(p,0.,1.);}');
  const f = mk(gl.FRAGMENT_SHADER, fs);
  if (!v || !f) return null;
  const p = gl.createProgram();
  gl.attachShader(p, v); gl.attachShader(p, f);
  gl.bindAttribLocation(p, 0, 'p');
  gl.linkProgram(p);
  if (!gl.getProgramParameter(p, gl.LINK_STATUS)) return null;
  gl.useProgram(p);
  gl.bindBuffer(gl.ARRAY_BUFFER, gl.createBuffer());
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
  gl.enableVertexAttribArray(0);
  gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
  return p;
}
function u(name) { return name in U ? U[name] : (U[name] = gl.getUniformLocation(prog, name)); }
function release() {
  if (gl) { const x = gl.getExtension('WEBGL_lose_context'); gl = null; if (x) x.loseContext(); }
  prog = null;
}
/* No WebGL (or the browser reclaimed the context): the CSS layer takes over. */
function degrade() { root.dataset.render = 'fallback'; release(); }
function size() {
  if (!gl) return;
  const d = Math.min(window.devicePixelRatio || 1, 2) * scale;
  const W = Math.max(1, Math.round(w * d)), H = Math.max(1, Math.round(h * d));
  if (canvas.width !== W || canvas.height !== H) { canvas.width = W; canvas.height = H; }
  gl.viewport(0, 0, W, H);
}
/* Long frames for a while: drop the backing resolution instead of the frame rate. */
function adapt(dt) {
  ema += (dt - ema) * 0.08;
  if (++frames > 45 && ema > 0.034 && scale > 0.55) { scale *= 0.85; frames = 0; ema = 1 / 60; size(); }
}
function kick() {
  if (dead || raf || !gl || !onScreen || document.hidden) return;
  raf = requestAnimationFrame(frame);
}
function frame(now) {
  if (!root.isConnected) return teardown();
  raf = 0;
  if (!gl || !onScreen || document.hidden) { last = 0; return; }
  const dt = last ? Math.min((now - last) / 1000, 0.1) : 1 / 60;
  last = now;
  if (!calm) t += dt;
  const settling = step(dt);
  gl.uniform2f(u('uRes'), canvas.width, canvas.height);
  gl.uniform1f(u('uTime'), t);
  setUniforms();
  gl.drawArrays(gl.TRIANGLES, 0, 3);
  if (!calm) adapt(dt);
  if (!calm || settling) raf = requestAnimationFrame(frame); else last = 0;
}
/* Pointer position in shader space: y up, origin at the centre, height = 1. */
function local(e) {
  const r = canvas.getBoundingClientRect();
  const a = r.width / Math.max(1, r.height);
  return [((e.clientX - r.left) / Math.max(1, r.width) - 0.5) * a, 0.5 - (e.clientY - r.top) / Math.max(1, r.height)];
}
