surface.addEventListener('focus', placeStylus);
const DIRS = { ArrowLeft: [-1, 0], ArrowRight: [1, 0], ArrowUp: [0, 1], ArrowDown: [0, -1] };
surface.addEventListener('keydown', (e) => {
