@property --fxs-clay-fill {
  syntax: '<percentage>';
  inherits: true;
  initial-value: 55%;
}
.fxs-clay {
  --fxs-clay-ground: oklch(0.925 0.016 80);
  --fxs-clay-body: oklch(0.63 0.14 40);
  --fxs-clay-shade: oklch(0.55 0.07 262);
  --fxs-clay-ink: oklch(0.27 0.03 45);

  --fxs-clay-muted: color-mix(in oklch, var(--fxs-clay-ink) 60%, var(--fxs-clay-ground));
  --fxs-clay-chip: color-mix(in oklch, var(--fxs-clay-ground) 78%, transparent);
  --fxs-clay-rule: color-mix(in oklch, var(--fxs-clay-ink) 14%, transparent);
  --fxs-clay-track: color-mix(in oklch, var(--fxs-clay-ink) 14%, var(--fxs-clay-ground));
  --fxs-clay-out: cubic-bezier(.16, 1, .3, 1);
  --fxs-clay-spring: linear(0, 0.059, 0.197, 0.366, 0.548, 0.716, 0.855, 0.959, 1.034, 1.080, 1.101, 1.104, 1.096, 1.080, 1.061, 1.042, 1.026, 1.012, 1.002, 0.995, 0.991, 0.989, 0.989, 0.990, 0.992, 0.994, 0.996, 0.998, 0.999, 1.000, 1.001, 1.001, 1.001, 1.001, 1.001, 1.001, 1);

  container-type: inline-size;
  position: relative;
  inline-size: 100%;
  aspect-ratio: 5 / 4;
  min-block-size: 200px;
  max-block-size: 380px;
  border-radius: 16px;
  overflow: hidden;
  isolation: isolate;
  background: var(--fxs-clay-ground);
  color: var(--fxs-clay-ink);
  font-family: system-ui, sans-serif;
  box-shadow: inset 0 0 0 1px var(--fxs-clay-rule);

  & .fxs-clay__gl,
  & .fxs-clay__fallback,
  & .fxs-clay__surface { position: absolute; inset: 0; inline-size: 100%; block-size: 100%; }
  & .fxs-clay__gl { display: block; }
  & .fxs-clay__surface {
    z-index: 1;
    cursor: grab;
    touch-action: none;
    border-radius: inherit;
    outline: none;
  }
  & .fxs-clay__surface:active { cursor: grabbing; }
  & .fxs-clay__surface:focus-visible {
    box-shadow: inset 0 0 0 2px var(--fxs-clay-body), inset 0 0 0 5px color-mix(in oklch, var(--fxs-clay-body) 25%, transparent);
  }
  & .fxs-clay__ui {
    position: absolute;
    inset: 0;
    z-index: 2;
    display: grid;
    grid-template-columns: 1fr auto;
    grid-template-rows: auto 1fr auto;
    grid-template-areas: "head formula" ". ." "control control";
    gap: 8px;
    padding: clamp(10px, 4cqi, 18px);
    pointer-events: none;
  }
  & .fxs-clay__head { grid-area: head; display: grid; gap: 3px; justify-items: start; }
  & .fxs-clay__eyebrow {
    font: 600 clamp(9px, 2.4cqi, 10.5px)/1.2 ui-monospace, Menlo, monospace;
    letter-spacing: .14em;
    text-transform: uppercase;
    color: var(--fxs-clay-muted);
  }
  & .fxs-clay__title {
    margin: 0;
    font-size: clamp(19px, 7cqi, 28px);
    font-weight: 700;
    letter-spacing: -.035em;
    line-height: 1;
    text-wrap: balance;
  }
  & .fxs-clay__formula {
    grid-area: formula;
    align-self: start;
    padding: 5px 8px;
    border-radius: 8px;
    background: var(--fxs-clay-chip);
    box-shadow: 0 0 0 1px var(--fxs-clay-rule);
    font: 500 11px/1.2 ui-monospace, Menlo, monospace;
    & var { font-style: italic; color: var(--fxs-clay-body); font-weight: 700; }
  }
  & .fxs-clay__control {
    grid-area: control;
    pointer-events: auto;
    display: grid;
    grid-template-columns: auto 1fr auto;
    align-items: center;
    gap: 10px;
    padding: 8px 12px;
    border-radius: 13px;
    background: var(--fxs-clay-chip);
    box-shadow: 0 0 0 1px var(--fxs-clay-rule), 0 10px 26px -18px color-mix(in oklch, var(--fxs-clay-ink) 70%, transparent);
    backdrop-filter: blur(8px) saturate(1.15);
  }
  & .fxs-clay__head,
  & .fxs-clay__formula,
  & .fxs-clay__control {
    transition: opacity .6s var(--fxs-clay-out) calc(var(--i, 0) * 60ms + 150ms), translate .7s var(--fxs-clay-out) calc(var(--i, 0) * 60ms + 150ms);
    @starting-style { opacity: 0; translate: 0 8px; }
  }
  & .fxs-clay__label { font-size: 12px; font-weight: 600; letter-spacing: -.005em; }
  & .fxs-clay__range {
    --fxs-clay-fill: 55%;
    appearance: none;
    inline-size: 100%;
    block-size: 18px;
    margin: 0;
    background: transparent;
    accent-color: var(--fxs-clay-body);
    cursor: pointer;
    transition: --fxs-clay-fill .35s var(--fxs-clay-out);
    &::-webkit-slider-runnable-track {
      block-size: 4px;
      border-radius: 4px;
      background: linear-gradient(90deg, var(--fxs-clay-body) var(--fxs-clay-fill), var(--fxs-clay-track) 0);
    }
    &::-moz-range-track { block-size: 4px; border-radius: 4px; background: var(--fxs-clay-track); }
    &::-moz-range-progress { block-size: 4px; border-radius: 4px; background: var(--fxs-clay-body); }
    &::-webkit-slider-thumb {
      appearance: none;
      inline-size: 16px;
      block-size: 16px;
      margin-block-start: -6px;
      border-radius: 50%;
      background: var(--fxs-clay-ground);
      box-shadow: 0 0 0 1.5px var(--fxs-clay-body), 0 2px 6px -1px color-mix(in oklch, var(--fxs-clay-ink) 50%, transparent);
      transition: scale .4s var(--fxs-clay-spring);
    }
    &::-moz-range-thumb {
      inline-size: 16px; block-size: 16px; border: 0; border-radius: 50%;
      background: var(--fxs-clay-ground);
      box-shadow: 0 0 0 1.5px var(--fxs-clay-body);
    }
    &:active::-webkit-slider-thumb { scale: 1.25; }
    &:focus-visible { outline: 2px solid var(--fxs-clay-body); outline-offset: 3px; border-radius: 6px; }
  }
  & .fxs-clay__value {
    min-inline-size: 6.5ch;
    text-align: end;
    font: 500 12px/1 ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
    color: var(--fxs-clay-muted);
    & var { font-style: italic; }
    & b { color: var(--fxs-clay-ink); font-weight: 650; }
  }
  & .fxs-clay__sr { position: absolute; inline-size: 1px; block-size: 1px; overflow: hidden;
    clip-path: inset(50%); white-space: nowrap; }

  /* No WebGL: three lit spheres with contact shadows, drifting together. */
  & .fxs-clay__fallback {
    display: none;
    & i {
      position: absolute;
      left: calc(26% + var(--i) * (22% - var(--k, .55) * 9%));
      transition: left .5s var(--fxs-clay-spring);
      top: calc(44% + var(--i) * 4%);
      inline-size: calc(26% - var(--i) * 5%);
      aspect-ratio: 1;
      border-radius: 50%;
      background: radial-gradient(circle at 34% 30%, color-mix(in oklch, var(--fxs-clay-body) 60%, white), var(--fxs-clay-body) 46%, color-mix(in oklch, var(--fxs-clay-body) 70%, var(--fxs-clay-shade)) 100%);
      box-shadow: 18px 22px 26px -10px color-mix(in oklch, var(--fxs-clay-shade) 55%, transparent);
      animation: fxs-clay-drift 7s var(--fxs-clay-out) calc(var(--i) * -2.3s) infinite alternate;
    }
  }
  &[data-render="fallback"] .fxs-clay__fallback { display: block; }
  &[data-render="fallback"] .fxs-clay__gl { display: none; }
}
@keyframes fxs-clay-drift {
  to { translate: -14% 6%; }
}
@container (inline-size < 300px) {
  .fxs-clay .fxs-clay__formula { display: none; }
  .fxs-clay .fxs-clay__label { display: none; }
}
@media (prefers-reduced-motion: reduce) {
  .fxs-clay {
    & .fxs-clay__fallback i { animation: none; }
    & .fxs-clay__head,
    & .fxs-clay__formula,
    & .fxs-clay__control { transition: opacity .2s linear; }
    & .fxs-clay__range { transition: none; }
  }
}

