const FRAG = `#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif
uniform vec2 uRes;
uniform float uTime;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * .1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}
float vnoise(vec2 p) {
  vec2 i = floor(p), f = fract(p);
  vec2 w = f * f * (3. - 2. * f);
  return mix(mix(hash12(i), hash12(i + vec2(1., 0.)), w.x),
             mix(hash12(i + vec2(0., 1.)), hash12(i + vec2(1., 1.)), w.x), w.y);
}
const mat2 OCT = mat2(.8, .6, -.6, .8);
float fbm(vec2 p) {
  float a = .5, s = 0.;
  for (int i = 0; i < 5; i++) { s += a * vnoise(p); p = OCT * p * 2.03; a *= .5; }
  return s;
}

uniform vec3 uGround, uBody, uShade, uLight;
uniform vec4 uB[4];      /* xyz centre, w radius */
uniform float uK;

float smin(float a, float b, float k) {
  float h = max(k - abs(a - b), 0.) / k;
  return min(a, b) - h * h * k * .25;
}
float blobs(vec3 p) {
  float d = length(p - uB[0].xyz) - uB[0].w;
  for (int i = 1; i < 4; i++) d = smin(d, length(p - uB[i].xyz) - uB[i].w, uK);
  return d;
}
/* x: distance · y: 1 on clay, 0 on the table (blended through the fillet) */
vec2 map(vec3 p) {
  float b = blobs(p), f = p.y;
  return vec2(smin(b, f, .07), clamp(.5 + .5 * (f - b) / .07, 0., 1.));
}
vec3 normal(vec3 p) {
  const vec2 e = vec2(.0015, -.0015);
  return normalize(e.xyy * map(p + e.xyy).x + e.yyx * map(p + e.yyx).x +
                   e.yxy * map(p + e.yxy).x + e.xxx * map(p + e.xxx).x);
}
/* Soft shadow: track how closely the shadow ray grazes the clay (penumbra ∝ h/t). */
float shadow(vec3 ro, vec3 rd) {
  float res = 1., t = .03;
  for (int i = 0; i < 40; i++) {
    float h = blobs(ro + rd * t);
    res = min(res, 7. * h / t);
    t += clamp(h, .015, .22);
    if (res < .002 || t > 3.5) break;
  }
  res = clamp(res, 0., 1.);
  return res * res * (3. - 2. * res);
}
float occlusion(vec3 p, vec3 n) {
  float o = 0., s = 1.;
  for (int i = 1; i <= 5; i++) {
    float hh = .015 + .06 * float(i);
    o += (hh - map(p + n * hh).x) * s;
    s *= .72;
  }
  return clamp(1. - 2.4 * o, 0., 1.);
}
void main() {
  vec2 p = (gl_FragCoord.xy - .5 * uRes) / uRes.y;
  vec3 ro = vec3(0., 1.45, 2.7);
  vec3 fw = normalize(vec3(0., .28, 0.) - ro);
  vec3 rt = normalize(cross(fw, vec3(0., 1., 0.)));
  vec3 up = cross(rt, fw);
  vec3 rd = normalize(p.x * rt + p.y * up + 1.9 * fw);

  vec3 G = pow(uGround, vec3(2.2)), B = pow(uBody, vec3(2.2)), S = pow(uShade, vec3(2.2));
  vec3 back = G * mix(1.06, .9, smoothstep(.5, -.5, p.y));
  vec3 col = back;

  float t = 0., hit = 0.;
  for (int i = 0; i < 96; i++) {
    float d = map(ro + rd * t).x;
    if (d < .0006 * t) { hit = 1.; break; }
    t += d;
    if (t > 9.) break;
  }
  if (hit > .5) {
    vec3 pos = ro + rd * t;
    vec2 m = map(pos);
    vec3 n = normal(pos);
    vec3 L = normalize(uLight);
    vec3 key = vec3(1., .95, .88) * 1.3;
    vec3 sky = mix(G, vec3(.82, .88, 1.), .4);
    float sh = shadow(pos + n * .003, L);
    float occ = occlusion(pos, n);
    vec3 tint = mix(S * 1.25, vec3(1.), sh);          /* cool penumbra, never grey */
