.fxs-halftone {
  --fxs-halftone-paper: oklch(0.972 0.012 92);
  --fxs-halftone-cyan: oklch(0.72 0.13 225);
  --fxs-halftone-magenta: oklch(0.62 0.23 355);
  --fxs-halftone-yellow: oklch(0.91 0.17 100);
  --fxs-halftone-key: oklch(0.24 0.012 270);

  --fxs-halftone-ink: color-mix(in oklch, var(--fxs-halftone-key) 92%, var(--fxs-halftone-paper));
  --fxs-halftone-muted: color-mix(in oklch, var(--fxs-halftone-key) 55%, var(--fxs-halftone-paper));
  --fxs-halftone-chip: color-mix(in oklch, var(--fxs-halftone-paper) 90%, transparent);
  --fxs-halftone-rule: color-mix(in oklch, var(--fxs-halftone-key) 15%, transparent);
  --fxs-halftone-out: cubic-bezier(.16, 1, .3, 1);
  --fxs-halftone-spring: linear(0, 0.051, 0.172, 0.328, 0.492, 0.646, 0.780, 0.889, 0.970, 1.026, 1.060, 1.078, 1.082, 1.077, 1.067, 1.054, 1.041, 1.028, 1.017, 1.009, 1.002, 0.998, 0.995, 0.994, 0.993, 0.994, 0.995, 0.996, 0.997, 0.998, 0.999, 0.999, 1.000, 1.000, 1.000, 1.001, 1);

  container-type: inline-size;
  position: relative;
  inline-size: 100%;
  aspect-ratio: 5 / 4;
  min-block-size: 200px;
  max-block-size: 380px;
  border-radius: 16px;
  overflow: hidden;
  isolation: isolate;
  background: var(--fxs-halftone-paper);
  color: var(--fxs-halftone-ink);
  font-family: system-ui, sans-serif;
  box-shadow: inset 0 0 0 1px var(--fxs-halftone-rule);

  & .fxs-halftone__gl,
  & .fxs-halftone__fallback,
  & .fxs-halftone__surface { position: absolute; inset: 0; inline-size: 100%; block-size: 100%; }
  & .fxs-halftone__gl { display: block; }
  & .fxs-halftone__surface { z-index: 1; cursor: move; touch-action: pan-y; border-radius: inherit; outline: none; }
  & .fxs-halftone__surface:focus-visible {
    box-shadow: inset 0 0 0 2px var(--fxs-halftone-magenta), inset 0 0 0 5px color-mix(in oklch, var(--fxs-halftone-magenta) 22%, transparent);
  }
  & .fxs-halftone__ui {
    position: absolute;
    inset: 0;
    z-index: 2;
    display: grid;
    grid-template-columns: 1fr auto;
    grid-template-rows: auto 1fr auto auto;
    grid-template-areas: "head mark" ". ." "controls controls" "bar bar";
    gap: 8px;
    padding: clamp(10px, 4cqi, 16px) clamp(10px, 4cqi, 16px) 0;
    pointer-events: none;
  }
  & .fxs-halftone__head {
    grid-area: head;
    justify-self: start;
    display: grid;
    gap: 3px;
    padding: 7px 10px 8px;
    border-radius: 10px;
    background: var(--fxs-halftone-chip);
    box-shadow: 0 0 0 1px var(--fxs-halftone-rule);
  }
  & .fxs-halftone__eyebrow {
    font: 600 clamp(9px, 2.3cqi, 10px)/1.2 ui-monospace, Menlo, monospace;
    letter-spacing: .14em;
    text-transform: uppercase;
    color: var(--fxs-halftone-muted);
  }
  & .fxs-halftone__title {
    margin: 0;
    font-size: clamp(15px, 5.2cqi, 21px);
    font-weight: 760;
    letter-spacing: -.025em;
    line-height: 1.05;
    text-wrap: balance;
