    & [data-plate="c"] { stroke: var(--fxs-halftone-cyan); }
    & [data-plate="m"] { stroke: var(--fxs-halftone-magenta); }
    & [data-plate="y"] { stroke: var(--fxs-halftone-yellow); }
    & [data-plate="k"] { stroke: var(--fxs-halftone-key); }
  }
  & .fxs-halftone__controls {
