      color: var(--fxs-halftone-muted);
      font: 600 11.5px/1 system-ui, sans-serif;
      letter-spacing: .01em;
      cursor: pointer;
      transition: color .25s, opacity .5s var(--fxs-halftone-out) calc(var(--i) * 50ms + 150ms), translate .6s var(--fxs-halftone-out) calc(var(--i) * 50ms + 150ms);
