  }
  & .fxs-halftone__reg {
    padding: 6px 9px;
    border-radius: 9px;
    background: var(--fxs-halftone-chip);
    box-shadow: 0 0 0 1px var(--fxs-halftone-rule);
    font: 500 11px/1 ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
    color: var(--fxs-halftone-muted);
    white-space: nowrap;
    & b { display: inline-block; min-inline-size: 3.5ch; text-align: end; color: var(--fxs-halftone-ink); font-weight: 650; }
  }
  & .fxs-halftone__reg[data-off] b { color: var(--fxs-halftone-magenta); }
  /* The press sheet's colour bar: solids, overprints and a 50% key tint. */
  & .fxs-halftone__bar {
    grid-area: bar;
    display: grid;
    grid-template-columns: repeat(8, 1fr);
    block-size: 9px;
    margin-inline: calc(-1 * clamp(10px, 4cqi, 16px));
    & i { display: block; }
    & [data-p="c"] { background: var(--fxs-halftone-cyan); }
    & [data-p="m"] { background: var(--fxs-halftone-magenta); }
    & [data-p="y"] { background: var(--fxs-halftone-yellow); }
    & [data-p="k"] { background: var(--fxs-halftone-key); }
    & [data-p="cm"] { background: linear-gradient(var(--fxs-halftone-cyan), var(--fxs-halftone-cyan)), var(--fxs-halftone-magenta); background-blend-mode: multiply; }
    & [data-p="my"] { background: linear-gradient(var(--fxs-halftone-magenta), var(--fxs-halftone-magenta)), var(--fxs-halftone-yellow); background-blend-mode: multiply; }
    & [data-p="cy"] { background: linear-gradient(var(--fxs-halftone-cyan), var(--fxs-halftone-cyan)), var(--fxs-halftone-yellow); background-blend-mode: multiply; }
    & [data-p="k50"] { background: radial-gradient(circle, var(--fxs-halftone-key) 0 1.6px, transparent 2px) 0 0 / 4px 4px, var(--fxs-halftone-paper); }
  }
  & .fxs-halftone__head,
  & .fxs-halftone__mark,
  & .fxs-halftone__reg {
    transition: opacity .6s var(--fxs-halftone-out) .1s, translate .7s var(--fxs-halftone-out) .1s;
