  }
  & .fxs-halftone__sr { position: absolute; inline-size: 1px; block-size: 1px; overflow: hidden;
    clip-path: inset(50%); white-space: nowrap; }

  /* No WebGL: three rotated dot screens multiplied over the paper. */
