    display: none;
    overflow: hidden;
    & i {
      position: absolute;
      inset: -40%;
      mix-blend-mode: multiply;
      background: radial-gradient(circle, var(--c) 0 calc(var(--pitch, 6.5px) * .3), transparent calc(var(--pitch, 6.5px) * .36)) 0 0 / var(--pitch, 6.5px) var(--pitch, 6.5px);
