    & [data-plate="m"] { --c: var(--fxs-halftone-magenta); rotate: 75deg; mask: linear-gradient(#000 0 62%, transparent 62%); }
    & [data-plate="y"] { --c: var(--fxs-halftone-yellow); rotate: 0deg; mask: none; }
  }
  &[data-render="fallback"] .fxs-halftone__fallback { display: block; }
  &[data-render="fallback"] .fxs-halftone__gl { display: none; }
}
@keyframes fxs-halftone-drift {
  to { translate: 3px -2px; }
}
@container (inline-size < 310px) {
  .fxs-halftone .fxs-halftone__lbl { display: none; }
  .fxs-halftone .fxs-halftone__seg button { padding-inline: 7px; }
  .fxs-halftone .fxs-halftone__eyebrow { display: none; }
}
@media (prefers-reduced-motion: reduce) {
  .fxs-halftone {
    & .fxs-halftone__fallback i { animation: none; }
    & .fxs-halftone__seg::before { transition: none; }
    & .fxs-halftone__seg button,
    & .fxs-halftone__head,
    & .fxs-halftone__mark,
    & .fxs-halftone__reg { transition: color .2s, opacity .2s linear; }
  }
}

