const FRAG = `#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif
uniform vec2 uRes;
uniform float uTime;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * .1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}
float vnoise(vec2 p) {
  vec2 i = floor(p), f = fract(p);
  vec2 w = f * f * (3. - 2. * f);
  return mix(mix(hash12(i), hash12(i + vec2(1., 0.)), w.x),
             mix(hash12(i + vec2(0., 1.)), hash12(i + vec2(1., 1.)), w.x), w.y);
}
const mat2 OCT = mat2(.8, .6, -.6, .8);
float fbm(vec2 p) {
  float a = .5, s = 0.;
  for (int i = 0; i < 5; i++) { s += a * vnoise(p); p = OCT * p * 2.03; a *= .5; }
  return s;
}

uniform vec3 uPaper, uCyan, uMagenta, uYellow, uKey;
uniform float uCell;     /* dot pitch, device px */
uniform vec2 uMis;       /* plate misregistration, device px */

mat2 rot(float a) { float c = cos(a), s = sin(a); return mat2(c, s, -s, c); }

/* The artwork being printed: a ringed planet poster, in plain RGB. */
vec3 scene(vec2 p) {
  vec3 col = mix(vec3(.98, .58, .52), vec3(1., .91, .6), smoothstep(-.32, .46, p.y));
  float sun = length(p - vec2(-.5, -.13));
  col = mix(col, vec3(1., .985, .93), 1. - smoothstep(.13, .135, sun));
  if (p.y < -.25) {
    col = mix(vec3(.3, .66, .64), vec3(.14, .4, .5), smoothstep(-.25, -.52, p.y));
    float sh = length((p - vec2(.2, -.31)) * vec2(1., 4.2));
    col *= mix(.62, 1., smoothstep(.16, .34, sh));
  }
  vec2 c = vec2(.13, .03 + .012 * sin(uTime * .7));
  vec2 q = rot(.34) * (p - c);
  float e = length(q * vec2(1., 3.4));
  float ring = smoothstep(.335, .345, e) * (1. - smoothstep(.43, .44, e));
  ring *= .75 + .25 * smoothstep(.36, .4, e);
  vec3 ringCol = vec3(.93, .36, .48);
  col = mix(col, ringCol, ring * step(0., q.y));
  float R = .25, l = length(p - c);
  if (l < R) {
    vec3 n = vec3((p - c) / R, sqrt(max(0., 1. - l * l / (R * R))));
    float a = uTime * .25;
    vec3 L = normalize(vec3(cos(a) * .8 - .4, .55, .75));
    float dif = max(dot(n, L), 0.);
    float bands = .5 + .5 * sin((n.y + .08 * n.x) * 15. + vnoise(n.xy * 5. + uTime * .05) * 2.);
    vec3 base = mix(vec3(.22, .64, .84), vec3(.8, .94, .95), bands * .6);
    col = base * (.4 + .68 * dif);
    col += pow(max(dot(reflect(-L, n), vec3(0., 0., 1.)), 0.), 30.) * .7;
  }
  col = mix(col, ringCol * (.85 + .15 * smoothstep(-.1, .1, q.x)), ring * step(q.y, 0.));
  return clamp(col, 0., 1.);
}
float plate(vec3 c, int ch) {
  float k = 1. - max(c.r, max(c.g, c.b));
  float kk = k * .55;                                   /* grey-component replacement */
  vec3 cmy = (1. - c - kk) / max(1. - kk, 1e-3);
  if (ch == 0) return cmy.r;
  if (ch == 1) return cmy.g;
  if (ch == 2) return cmy.b;
  return kk;
}
/* One screen: rotate into the screen's grid, find this cell's centre, sample the
   artwork there and draw a dot whose area equals the ink coverage. */
float screen(vec2 px, float ang, int ch, vec2 off) {
  mat2 r = rot(ang);
  vec2 q = r * (px - off);
  vec2 cc = (floor(q / uCell) + .5) * uCell;
  vec2 back = cc * r + off;                              /* r is orthonormal: transpose = inverse */
  float cov = clamp(plate(scene((back - .5 * uRes) / uRes.y), ch), 0., 1.);
  float rad = uCell * sqrt(cov / 3.14159) * 1.04;
  float d = length(q - cc);
  return 1. - smoothstep(rad - .75, rad + .75, d);
}
void main() {
  vec2 px = gl_FragCoord.xy;
  vec2 p = (px - .5 * uRes) / uRes.y;
  float c = screen(px, radians(15.), 0, uMis * vec2(1., .35));
  float m = screen(px, radians(75.), 1, uMis * vec2(-.55, .9));
  float y = screen(px, radians(0.), 2, uMis * vec2(.25, -1.1));
  float k = screen(px, radians(45.), 3, vec2(0.));
  float grain = vnoise(px * .35) * .5 + vnoise(px * .09) * .5;
  vec3 col = uPaper * (1. - .035 * grain);
  float ink = .9 + .1 * vnoise(p * 9. + 3.);              /* uneven inking across the sheet */
  col *= mix(vec3(1.), uCyan, c * ink);
  col *= mix(vec3(1.), uMagenta, m * ink);
  col *= mix(vec3(1.), uYellow, y);
  col *= mix(vec3(1.), uKey, k);
  gl_FragColor = vec4(col, 1.);
}
`;
const T0 = 2;
const seg = root.querySelector('.fxs-halftone__seg');
const fallback = root.querySelector('.fxs-halftone__fallback');
const segBtns = [...seg.querySelectorAll('button')];
const surface = root.querySelector('.fxs-halftone__surface');
const regOut = root.querySelector('.fxs-halftone__reg');
const regVal = regOut.querySelector('b');
const live = root.querySelector('.fxs-halftone__sr');
const plates = {};
root.querySelectorAll('.fxs-halftone__plate').forEach((g) => { plates[g.dataset.plate] = g; });
/* Plate directions match the shader's offsets, so the corner mark tells the truth. */
const DIR = { c: [1, .35], m: [-.55, .9], y: [.25, -1.1], k: [0, 0] };
const pal = {};
const mis = [0, 0], hoverOff = [0, 0], manual = [0, 0];
let pitch = 6.5, hovering = false, shownReg = '';

/* ── shader host ───────────────────────────────────────────────────────────
   One full-screen triangle. DPR-aware sizing (capped), adaptive resolution
   when frames run long, paused off screen and in hidden tabs, theme colours
   resolved from the root's custom properties, and the WebGL context released
   as soon as the component leaves the document. */
const canvas = root.querySelector('.fxs-halftone__gl');
const probe = root.querySelector('.fxs-halftone__probe');
