let calm = motionQ.matches;
const swatch = Object.assign(document.createElement('canvas'), { width: 1, height: 1 })
  .getContext('2d', { willReadFrequently: true });
/* Resolve a custom property (oklch, color-mix, var chains…) to linear-free sRGB 0..1. */
function rgb(prop) {
