/* Pointer position in shader space: y up, origin at the centre, height = 1. */
function local(e) {
  const r = canvas.getBoundingClientRect();
  const a = r.width / Math.max(1, r.height);
  return [((e.clientX - r.left) / Math.max(1, r.width) - 0.5) * a, 0.5 - (e.clientY - r.top) / Math.max(1, r.height)];
