/* Frame-rate independent easing toward a target; snaps when motion is reduced. */
function approach(a, b, dt, rate) { return calm ? b : a + (b - a) * (1 - Math.exp(-rate * dt)); }
{
  const r = canvas.getBoundingClientRect();
  w = r.width || 300; h = r.height || 150;
  size();
}
const ro = new ResizeObserver(([e]) => { w = e.contentRect.width; h = e.contentRect.height; size(); kick(); });
ro.observe(canvas);
const io = new IntersectionObserver(([e]) => { onScreen = e.isIntersecting; kick(); }, { rootMargin: '80px' });
io.observe(root);
const onVis = () => kick();
document.addEventListener('visibilitychange', onVis);
const onMotion = () => { calm = motionQ.matches; onCalm(); kick(); };
motionQ.addEventListener('change', onMotion);
/* Re-theme live: overriding a --fxs-halftone-* variable on the root recolours the shader. */
const mo = new MutationObserver(() => { theme(); kick(); });
mo.observe(root, { attributes: true, attributeFilter: ['style', 'class', 'data-theme'] });
