}
/* ── end host ── */

function theme() {
  pal.paper = rgb('--fxs-halftone-paper');
  pal.cyan = rgb('--fxs-halftone-cyan');
  pal.magenta = rgb('--fxs-halftone-magenta');
  pal.yellow = rgb('--fxs-halftone-yellow');
  pal.key = rgb('--fxs-halftone-key');
}
function step(dt) {
  /* Target in CSS px: the pointer's pull, plus any manual nudge, plus a faint press wobble. */
  const wob = calm ? 0 : .5;
  const tx = manual[0] + hoverOff[0] + wob * Math.sin(t * 1.3);
  const ty = manual[1] + hoverOff[1] + wob * Math.cos(t * .9);
  mis[0] = approach(mis[0], tx, dt, 7);
  mis[1] = approach(mis[1], ty, dt, 7);
  for (const k in plates) {
    plates[k].style.setProperty('--dx', (mis[0] * DIR[k][0] * .35).toFixed(2));
    plates[k].style.setProperty('--dy', (-mis[1] * DIR[k][1] * .35).toFixed(2));
  }
  const mag = Math.hypot(manual[0] + hoverOff[0], manual[1] + hoverOff[1]);
  const txt = mag.toFixed(1);
