  gl.uniform3fv(u('uCyan'), pal.cyan);
  gl.uniform3fv(u('uMagenta'), pal.magenta);
  gl.uniform3fv(u('uYellow'), pal.yellow);
  gl.uniform3fv(u('uKey'), pal.key);
