theme();
kick();

css:
@property --fxs-aurora-sway {
  syntax: '<angle>';
  inherits: false;
  initial-value: 0deg;
}
.fxs-aurora {
  --fxs-aurora-sky: oklch(0.17 0.03 215);
  --fxs-aurora-green: oklch(0.86 0.2 150);
  --fxs-aurora-rose: oklch(0.64 0.2 8);
  --fxs-aurora-land: oklch(0.11 0.015 230);

  --fxs-aurora-text: oklch(0.96 0.01 150);
  --fxs-aurora-muted: color-mix(in oklch, var(--fxs-aurora-text) 62%, var(--fxs-aurora-sky));
  --fxs-aurora-chip: color-mix(in oklch, var(--fxs-aurora-land) 62%, transparent);
  --fxs-aurora-rule: color-mix(in oklch, var(--fxs-aurora-text) 14%, transparent);
  --fxs-aurora-quiet: oklch(0.8 0.15 150);
  --fxs-aurora-minor: oklch(0.85 0.15 95);
  --fxs-aurora-strong: oklch(0.75 0.17 55);
  --fxs-aurora-severe: oklch(0.66 0.21 25);
  --fxs-aurora-out: cubic-bezier(.16, 1, .3, 1);
  --fxs-aurora-spring: linear(0, 0.049, 0.165, 0.316, 0.475, 0.625, 0.757, 0.865, 0.948, 1.008, 1.046, 1.066, 1.073, 1.072, 1.064, 1.054, 1.042, 1.031, 1.021, 1.012, 1.005, 1.001, 0.997, 0.996, 0.995, 0.995, 0.995, 0.996, 0.997, 0.998, 0.998, 0.999, 0.999, 1.000, 1.000, 1.000, 1);

  container-type: inline-size;
  position: relative;
  inline-size: 100%;
  aspect-ratio: 5 / 4;
  min-block-size: 200px;
  max-block-size: 380px;
  border-radius: 16px;
  overflow: hidden;
  isolation: isolate;
  background: var(--fxs-aurora-sky);
  color: var(--fxs-aurora-text);
  font-family: system-ui, sans-serif;

  & .fxs-aurora__gl,
  & .fxs-aurora__fallback,
  & .fxs-aurora__surface { position: absolute; inset: 0; inline-size: 100%; block-size: 100%; }
  & .fxs-aurora__gl { display: block; }
  & .fxs-aurora__surface { z-index: 1; }
  & .fxs-aurora__ui {
    position: absolute;
    inset: 0;
    z-index: 2;
    display: grid;
    grid-template-columns: 1fr auto;
    grid-template-rows: auto 1fr auto;
    grid-template-areas: "head status" ". ." "control control";
    gap: 8px;
    padding: clamp(10px, 4cqi, 18px);
    pointer-events: none;
  }
  & .fxs-aurora__head { grid-area: head; display: grid; gap: 3px; align-content: start; }
  & .fxs-aurora__eyebrow {
    font: 600 clamp(9px, 2.4cqi, 10.5px)/1.2 ui-monospace, Menlo, monospace;
    letter-spacing: .14em;
    text-transform: uppercase;
    color: var(--fxs-aurora-muted);
  }
  & .fxs-aurora__title {
    margin: 0;
    font-size: clamp(19px, 7cqi, 28px);
    font-weight: 680;
    letter-spacing: -.03em;
    line-height: 1;
    text-wrap: balance;
    text-shadow: 0 1px 16px color-mix(in oklch, var(--fxs-aurora-land) 80%, transparent);
  }
  & .fxs-aurora__status {
    --tone: var(--fxs-aurora-minor);
    grid-area: status;
    display: grid;
    justify-items: end;
    align-content: start;
    gap: 4px;
  }
  & .fxs-aurora__status[data-level="quiet"] { --tone: var(--fxs-aurora-quiet); }
  & .fxs-aurora__status[data-level="active"] { --tone: var(--fxs-aurora-minor); }
  & .fxs-aurora__status[data-level="g1"],
  & .fxs-aurora__status[data-level="g2"] { --tone: var(--fxs-aurora-strong); }
  & .fxs-aurora__status[data-level="g3"],
  & .fxs-aurora__status[data-level="g4"],
  & .fxs-aurora__status[data-level="g5"] { --tone: var(--fxs-aurora-severe); }
  & .fxs-aurora__kp {
    display: flex;
    align-items: baseline;
    gap: 4px;
    font-variant-numeric: tabular-nums;
    & small { font: 600 11px/1 ui-monospace, Menlo, monospace; color: var(--fxs-aurora-muted); letter-spacing: .06em; }
    & b {
      display: inline-block;
      font-size: clamp(26px, 10cqi, 40px);
      font-weight: 300;
      line-height: .9;
      letter-spacing: -.04em;
    }
    & b.is-tick { animation: fxs-aurora-tick .55s var(--fxs-aurora-spring); }
  }
  & .fxs-aurora__scale {
    padding: 4px 8px;
    border-radius: 99px;
    background: color-mix(in oklch, var(--tone) 18%, transparent);
    box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--tone) 45%, transparent);
    color: var(--tone);
    font: 600 10.5px/1 system-ui, sans-serif;
    letter-spacing: .02em;
    white-space: nowrap;
    transition: color .4s, background-color .4s, box-shadow .4s;
  }
  & .fxs-aurora__control {
    grid-area: control;
    pointer-events: auto;
    display: grid;
    grid-template-columns: auto 1fr auto;
    grid-template-areas: "label range reach";
    align-items: center;
    column-gap: 10px;
    padding: 7px 12px;
    border-radius: 14px;
    background: var(--fxs-aurora-chip);
    box-shadow: inset 0 0 0 1px var(--fxs-aurora-rule);
    backdrop-filter: blur(10px) saturate(1.3);
  }
  & .fxs-aurora__head,
  & .fxs-aurora__status,
  & .fxs-aurora__control {
    transition: opacity .7s var(--fxs-aurora-out) .15s, translate .8s var(--fxs-aurora-out) .15s;
    @starting-style { opacity: 0; translate: 0 8px; }
  }
  & .fxs-aurora__label { grid-area: label; font-size: 12px; font-weight: 600; }
  & .fxs-aurora__reach {
    grid-area: reach;
    font: 500 11px/1.3 ui-monospace, Menlo, monospace;
    color: var(--fxs-aurora-muted);
    font-variant-numeric: tabular-nums;
    & b { color: var(--fxs-aurora-text); font-weight: 600; }
  }
  & .fxs-aurora__range {
    grid-area: range;
    appearance: none;
    inline-size: 100%;
    block-size: 18px;
    margin: 0;
    background: transparent;
    accent-color: var(--fxs-aurora-green);
    cursor: pointer;
    &::-webkit-slider-runnable-track {
      block-size: 4px;
      border-radius: 4px;
      background: linear-gradient(90deg, var(--fxs-aurora-quiet) 0 38.9%, var(--fxs-aurora-minor) 0 50%, var(--fxs-aurora-strong) 0 72.2%, var(--fxs-aurora-severe) 0);
    }
    &::-moz-range-track {
      block-size: 4px;
      border-radius: 4px;
      background: linear-gradient(90deg, var(--fxs-aurora-quiet) 0 38.9%, var(--fxs-aurora-minor) 0 50%, var(--fxs-aurora-strong) 0 72.2%, var(--fxs-aurora-severe) 0);
    }
    &::-webkit-slider-thumb {
      appearance: none;
      inline-size: 18px;
      block-size: 18px;
      margin-block-start: -7px;
      border-radius: 50%;
      background: var(--fxs-aurora-text);
      box-shadow: 0 0 0 4px color-mix(in oklch, var(--fxs-aurora-land) 70%, transparent), 0 0 18px var(--fxs-aurora-green);
      transition: scale .4s var(--fxs-aurora-spring);
    }
    &::-moz-range-thumb {
      inline-size: 18px; block-size: 18px; border: 0; border-radius: 50%;
      background: var(--fxs-aurora-text);
      box-shadow: 0 0 0 4px color-mix(in oklch, var(--fxs-aurora-land) 70%, transparent);
    }
    &:active::-webkit-slider-thumb { scale: 1.2; }
    &:focus-visible { outline: 2px solid var(--fxs-aurora-green); outline-offset: 4px; border-radius: 6px; }
  }
  & .fxs-aurora__sr { position: absolute; inline-size: 1px; block-size: 1px; overflow: hidden;
    clip-path: inset(50%); white-space: nowrap; }

  /* No WebGL: two blurred curtains sway over a CSS ridge line. */
  & .fxs-aurora__fallback {
    display: none;
    background: linear-gradient(to top, color-mix(in oklch, var(--fxs-aurora-sky) 80%, var(--fxs-aurora-green)), var(--fxs-aurora-sky) 55%);
    & i {
      position: absolute;
      inset: calc(34% - var(--kp, .55) * 26%) -10% 38%;
      background: linear-gradient(to top, var(--fxs-aurora-green), color-mix(in oklch, var(--fxs-aurora-rose) 60%, transparent) 60%, transparent);
      filter: blur(14px);
      opacity: calc(.3 + var(--kp, .55) * .65);
      clip-path: polygon(0 100%, 10% 40%, 25% 70%, 42% 20%, 60% 60%, 78% 10%, 100% 50%, 100% 100%);
      transform: skewX(var(--fxs-aurora-sway));
      animation: fxs-aurora-sway 8s ease-in-out calc(var(--i) * -3s) infinite alternate;
    }
    & b {
      position: absolute;
      inset: 55% 0 0;
      background: var(--fxs-aurora-land);
      clip-path: polygon(0 20%, 12% 8%, 24% 18%, 38% 0, 52% 16%, 68% 6%, 84% 20%, 100% 10%, 100% 100%, 0 100%);
    }
  }
  &[data-render="fallback"] .fxs-aurora__fallback { display: block; }
  &[data-render="fallback"] .fxs-aurora__gl { display: none; }
}
@keyframes fxs-aurora-sway {
  from { --fxs-aurora-sway: -12deg; }
  to { --fxs-aurora-sway: 14deg; }
}
@keyframes fxs-aurora-tick {
  0% { translate: 0 0; opacity: 1; }
  35% { translate: 0 -5px; opacity: .4; }
  100% { translate: 0 0; opacity: 1; }
}
@container (inline-size < 310px) {
  .fxs-aurora .fxs-aurora__label,
  .fxs-aurora .fxs-aurora__coord { display: none; }
  .fxs-aurora .fxs-aurora__scale { font-size: 9.5px; }
}
@media (prefers-reduced-motion: reduce) {
  .fxs-aurora {
    & .fxs-aurora__fallback i { animation: none; }
    & .fxs-aurora__kp b.is-tick { animation: none; }
    & .fxs-aurora__head,
    & .fxs-aurora__status,
    & .fxs-aurora__control { transition: opacity .2s linear; }
  }
}

