const FRAG = `#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif
uniform vec2 uRes;
uniform float uTime;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * .1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}
float vnoise(vec2 p) {
  vec2 i = floor(p), f = fract(p);
  vec2 w = f * f * (3. - 2. * f);
  return mix(mix(hash12(i), hash12(i + vec2(1., 0.)), w.x),
             mix(hash12(i + vec2(0., 1.)), hash12(i + vec2(1., 1.)), w.x), w.y);
}
const mat2 OCT = mat2(.8, .6, -.6, .8);
float fbm(vec2 p) {
  float a = .5, s = 0.;
  for (int i = 0; i < 5; i++) { s += a * vnoise(p); p = OCT * p * 2.03; a *= .5; }
  return s;
}

uniform vec3 uSky, uGreen, uRose, uLand;
uniform float uKp, uWind;

const float HZ = -.13;

/* The sheet folds along x. Where a fold bunches the sheet up, we look through more
   of it edge-on — so brightness is the inverse of the warp's slope. */
float warpX(float x, float s, float t) {
  return x + .16 * sin(x * 2.1 + t * .23 + s * 4. + uWind * .9)
           + .07 * sin(x * 5.3 - t * .31 + s * 9. - uWind * .5)
           + .05 * (vnoise(vec2(x * 3., t * .15 + s * 7.)) - .5);
}
vec3 curtain(vec2 p, float s, float t, float base, float amp) {
  float e = .002;
  float X = warpX(p.x, s, t), X2 = warpX(p.x + e, s, t);
  float fold = clamp(e / max(abs(X2 - X), 1e-4), .3, 3.5);
  float yb = base + .05 * sin(X * 2.3 + s * 3.) + .03 * vnoise(vec2(X * 4., t * .1 + s));
  float dy = p.y - yb;
  float H = .14 + .22 * uKp;
  float vert = dy > 0. ? exp(-dy / H) : exp(dy * 60.);
  float rays = .4 + .6 * pow(vnoise(vec2(X * 55., t * .45 + s * 13.)), 1.5);
  rays *= .65 + .35 * vnoise(vec2(X * 8., t * .2 + s));
  vec3 c = mix(uGreen, uRose, smoothstep(.04, .34, dy) * (.25 + .75 * uKp));
  c += vec3(.2, .3, .15) * exp(-abs(dy) * 55.) * .5;     /* hot lower hem */
  return c * vert * rays * fold * amp;
}
float ridge(float x) { return HZ + .008 + .14 * pow(clamp((fbm(vec2(x * 1.4 + 4., 1.3)) - .28) * 2.1, 0., 1.), 1.4); }
vec3 sky(vec2 p, float t) {
  float y = p.y - HZ;
  vec3 col = mix(uSky * 1.9, uSky * .55, smoothstep(0., .75, y));
  vec2 sp = p * 95.;
  vec2 id = floor(sp);
  float h = hash12(id);
  if (h > .962) {
    vec2 f = fract(sp) - .5 - (vec2(hash12(id + 3.1), hash12(id + 7.7)) - .5) * .6;
    float tw = .65 + .35 * sin(t * 2.2 + h * 70.);
    col += vec3(.92, .93, 1.) * smoothstep(.14, 0., length(f)) * tw * (h - .962) * 24.;
  }
  float act = mix(.4, 1.45, uKp);
  vec3 a = curtain(p, 0., t, HZ + .2 - .05 * uKp, act);
  a += curtain(p + vec2(.4, 0.), 1., t * .8, HZ + .31, .5 * act);
  a += curtain(p * vec2(1.3, 1.) + vec2(-.3, 0.), 2., t * 1.1, HZ + .13 - .04 * uKp, .65 * act);
  col += a * .5 + uGreen * .05 * act * (1. - smoothstep(0., .6, y));
  return col;
}
void main() {
  vec2 p = (gl_FragCoord.xy - .5 * uRes) / uRes.y;
  float px = 1.5 / uRes.y;
  float t = uTime;
  vec3 col;
  if (p.y > HZ) {
    col = sky(p, t);
    float r = ridge(p.x);
    vec3 land = uLand + uGreen * .03 * smoothstep(r - .05, r, p.y);
    col = mix(col, land, smoothstep(r + px, r - px, p.y));
  } else {
    /* The lake: mirror about the shoreline, ripples growing toward the viewer. */
    float dy = HZ - p.y;
    vec2 q = vec2(p.x + .005 * sin(dy * 170. - t * 1.4) * (.25 + dy * 3.), HZ + dy * (1. + .02 * sin(p.x * 40. + t)));
    col = sky(q, t);
    float r = ridge(q.x);
    col = mix(col, uLand, smoothstep(r + px, r - px, q.y));
    col *= .48;
    col = mix(col, uSky * .4, smoothstep(0., .3, dy) * .5);
    col += uGreen * .08 * exp(-dy * 90.) * mix(.4, 1.4, uKp);  /* shoreline glint */
  }
  col = col / (1. + col * .18);
  col += (hash12(gl_FragCoord.xy) - .5) / 255.;
  gl_FragColor = vec4(col, 1.);
}
`;
const T0 = 14;
/* NOAA's planetary K-index: geomagnetic storm scale and the approximate
