  ['quiet', 'Unsettled', 60.4], ['active', 'Active', 58.3], ['g1', 'G1 · Minor storm', 56.3],
  ['g2', 'G2 · Moderate storm', 54.2], ['g3', 'G3 · Strong storm', 52.2],
  ['g4', 'G4 · Severe storm', 50.1], ['g5', 'G5 · Extreme storm', 48.1],
