const range = root.querySelector('.fxs-aurora__range');
const fallback = root.querySelector('.fxs-aurora__fallback');
const status = root.querySelector('.fxs-aurora__status');
const kpEl = root.querySelector('.fxs-aurora__kp b');
const scaleEl = root.querySelector('.fxs-aurora__scale');
const reachEl = root.querySelector('.fxs-aurora__reach b');
const surface = root.querySelector('.fxs-aurora__surface');
const live = root.querySelector('.fxs-aurora__sr');
const pal = {};
let kp = 5 / 9, wind = 0, windT = 0;

/* ── shader host ───────────────────────────────────────────────────────────
