const dog = setInterval(() => { if (!root.isConnected) return teardown(); }, 2000);
function teardown() {
  if (dead) return;
  dead = true;
  cancelAnimationFrame(raf);
  clearInterval(dog);
  ro.disconnect(); io.disconnect(); mo.disconnect();
  document.removeEventListener('visibilitychange', onVis);
  motionQ.removeEventListener('change', onMotion);
  release();
}
/* ── end host ── */

function theme() {
  pal.sky = rgb('--fxs-aurora-sky');
  pal.green = rgb('--fxs-aurora-green');
  pal.rose = rgb('--fxs-aurora-rose');
  pal.land = rgb('--fxs-aurora-land');
}
function step(dt) {
  const target = range.value / 9;
  kp = approach(kp, target, dt, 2.2);
  const auto = calm ? 0 : .35 * Math.sin(t * .07);
  wind = approach(wind, windT + auto, dt, 1.6);
  return Math.abs(kp - target) > 1e-3 || Math.abs(wind - windT - auto) > 1e-3;
}
function setUniforms() {
  gl.uniform3fv(u('uSky'), pal.sky);
  gl.uniform3fv(u('uGreen'), pal.green);
  gl.uniform3fv(u('uRose'), pal.rose);
  gl.uniform3fv(u('uLand'), pal.land);
  gl.uniform1f(u('uKp'), kp);
  gl.uniform1f(u('uWind'), wind);
}
function onCalm() {}
/* Solar wind: the pointer leans on the curtains. */
surface.addEventListener('pointermove', (e) => {
  const p = local(e);
  windT = Math.max(-1, Math.min(1, p[0] / (w / Math.max(1, h) / 2))) * 1.4;
  kick();
});
