function sync(announce) {
  const v = +range.value;
  const [level, label, lat] = SCALE[v];
  if (kpEl.textContent !== String(v)) {
    kpEl.textContent = v;
    kpEl.classList.remove('is-tick');
    void kpEl.offsetWidth;
    kpEl.classList.add('is-tick');
  }
  status.dataset.level = level;
  fallback.style.setProperty('--kp', (v / 9).toFixed(3));
  scaleEl.textContent = label;
  reachEl.textContent = lat.toFixed(1) + '°';
  range.setAttribute('aria-valuetext', 'Kp ' + v + ', ' + label.replace(' · ', ' '));
  if (announce) live.textContent = 'Kp ' + v + ', ' + label.replace(' · ', ' ') + '. Visible to ' + lat.toFixed(1) + ' degrees latitude.';
  kick();
}
range.addEventListener('input', () => sync(false));
range.addEventListener('change', () => sync(true));

theme();
sync(false);
kick();

css:
@property --fxs-chrome-spin {
  syntax: '<angle>';
  inherits: false;
  initial-value: 0deg;
}
.fxs-chrome {
  --fxs-chrome-bg: oklch(0.21 0.008 70);
  --fxs-chrome-metal: oklch(0.91 0.016 85);
  --fxs-chrome-light: oklch(0.99 0.008 90);
  --fxs-chrome-warm: oklch(0.68 0.12 52);

  --fxs-chrome-text: color-mix(in oklch, var(--fxs-chrome-light) 92%, var(--fxs-chrome-bg));
  --fxs-chrome-muted: color-mix(in oklch, var(--fxs-chrome-light) 52%, var(--fxs-chrome-bg));
  --fxs-chrome-rule: color-mix(in oklch, var(--fxs-chrome-light) 12%, transparent);
  --fxs-chrome-chip: color-mix(in oklch, var(--fxs-chrome-bg) 70%, transparent);
  --fxs-chrome-out: cubic-bezier(.16, 1, .3, 1);
  --fxs-chrome-spring: linear(0, 0.100, 0.327, 0.595, 0.840, 1.022, 1.139, 1.189, 1.187, 1.152, 1.102, 1.051, 1.009, 0.981, 0.966, 0.963, 0.967, 0.976, 0.986, 0.995, 1.002, 1.006, 1.007, 1.007, 1.005, 1.004, 1.002, 1.000, 0.999, 0.999, 0.999, 0.999, 0.999, 1.000, 1.000, 1.000, 1);

  container-type: inline-size;
  position: relative;
  inline-size: 100%;
  aspect-ratio: 5 / 4;
  min-block-size: 200px;
  max-block-size: 380px;
  border-radius: 16px;
  overflow: hidden;
  isolation: isolate;
  background: var(--fxs-chrome-bg);
  color: var(--fxs-chrome-text);
  font-family: system-ui, sans-serif;

  & .fxs-chrome__gl,
  & .fxs-chrome__fallback,
  & .fxs-chrome__surface { position: absolute; inset: 0; inline-size: 100%; block-size: 100%; }
  & .fxs-chrome__gl { display: block; }
  & .fxs-chrome__surface { z-index: 1; cursor: pointer; touch-action: pan-y; border-radius: inherit; outline: none; }
  & .fxs-chrome__surface:focus-visible {
    box-shadow: inset 0 0 0 2px var(--fxs-chrome-warm), inset 0 0 0 5px color-mix(in oklch, var(--fxs-chrome-warm) 25%, transparent);
  }
  & .fxs-chrome__ui {
    position: absolute;
    inset: 0;
    z-index: 2;
    display: grid;
    grid-template-columns: 1fr auto;
    grid-template-rows: auto 1fr auto;
    grid-template-areas: "head head" ". ." "stats drip";
    align-items: end;
    gap: 8px;
    padding: clamp(10px, 4cqi, 18px);
    pointer-events: none;
  }
  & .fxs-chrome__head { grid-area: head; display: grid; gap: 3px; }
  & .fxs-chrome__eyebrow {
    font: 600 clamp(9px, 2.4cqi, 10.5px)/1.2 ui-monospace, Menlo, monospace;
    letter-spacing: .14em;
    text-transform: uppercase;
    color: var(--fxs-chrome-muted);
  }
  & .fxs-chrome__title {
    margin: 0;
    font-size: clamp(19px, 7cqi, 28px);
    font-weight: 300;
    letter-spacing: -.02em;
    line-height: 1;
    text-wrap: balance;
  }
  & .fxs-chrome__stats {
    grid-area: stats;
    display: flex;
    gap: clamp(10px, 4cqi, 18px);
    margin: 0;
    & div {
      display: grid;
      gap: 3px;
      transition: opacity .6s var(--fxs-chrome-out) calc(var(--i) * 60ms + 200ms), translate .7s var(--fxs-chrome-out) calc(var(--i) * 60ms + 200ms);
      @starting-style { opacity: 0; translate: 0 6px; }
    }
    & dt { font: 600 9px/1 ui-monospace, Menlo, monospace; letter-spacing: .12em; text-transform: uppercase; color: var(--fxs-chrome-muted); }
    & dd { margin: 0; font: 500 12.5px/1 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; white-space: nowrap; }
    & abbr { text-decoration: none; color: var(--fxs-chrome-muted); }
  }
  & .fxs-chrome__drip {
    grid-area: drip;
    pointer-events: auto;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 8px 12px 8px 10px;
    border: 0;
    border-radius: 99px;
    background: linear-gradient(180deg, color-mix(in oklch, var(--fxs-chrome-light) 16%, transparent), color-mix(in oklch, var(--fxs-chrome-light) 6%, transparent));
    box-shadow: inset 0 0 0 1px var(--fxs-chrome-rule), inset 0 1px 0 color-mix(in oklch, var(--fxs-chrome-light) 22%, transparent);
    color: var(--fxs-chrome-text);
    font: 600 12px/1 system-ui, sans-serif;
    cursor: pointer;
    backdrop-filter: blur(8px);
    transition: scale .45s var(--fxs-chrome-spring), background-color .2s, opacity .6s var(--fxs-chrome-out) .35s;
    @starting-style { opacity: 0; }
    & svg { inline-size: 14px; block-size: 14px; fill: var(--fxs-chrome-warm); transition: translate .5s var(--fxs-chrome-spring); }
    &:hover svg { translate: 0 2px; }
    &:active { scale: .93; }
    &:focus-visible { outline: 2px solid var(--fxs-chrome-warm); outline-offset: 2px; }
  }
  & .fxs-chrome__head {
    transition: opacity .7s var(--fxs-chrome-out) .1s, translate .8s var(--fxs-chrome-out) .1s;
    @starting-style { opacity: 0; translate: 0 -6px; }
  }
  & .fxs-chrome__count.is-up { animation: fxs-chrome-pop .5s var(--fxs-chrome-spring); }
  & .fxs-chrome__sr { position: absolute; inline-size: 1px; block-size: 1px; overflow: hidden;
    clip-path: inset(50%); white-space: nowrap; }

  /* No WebGL: a conic-gradient chrome bead turning slowly. */
  & .fxs-chrome__fallback {
    display: none;
    place-items: center;
    & i {
      inline-size: 58%;
      aspect-ratio: 1.15;
      border-radius: 50%;
      background:
        radial-gradient(ellipse at 50% 30%, color-mix(in oklch, var(--fxs-chrome-light) 70%, transparent) 0 12%, transparent 30%),
        conic-gradient(from var(--fxs-chrome-spin), var(--fxs-chrome-bg), var(--fxs-chrome-metal) 12%, var(--fxs-chrome-bg) 24%, var(--fxs-chrome-warm) 40%, var(--fxs-chrome-light) 52%, var(--fxs-chrome-bg) 66%, var(--fxs-chrome-metal) 82%, var(--fxs-chrome-bg));
      box-shadow: 0 18px 30px -12px #000a;
      animation: fxs-chrome-spin 14s linear infinite;
    }
    & i.is-drip { animation: fxs-chrome-spin 14s linear infinite, fxs-chrome-wobble .9s var(--fxs-chrome-spring); }
  }
  &[data-render="fallback"] .fxs-chrome__fallback { display: grid; }
  &[data-render="fallback"] .fxs-chrome__gl { display: none; }
}
@keyframes fxs-chrome-spin {
  to { --fxs-chrome-spin: 360deg; }
}
@keyframes fxs-chrome-wobble {
  0% { scale: 1; }
  20% { scale: 1.06 .94; }
  100% { scale: 1; }
}
@keyframes fxs-chrome-pop {
  0% { color: var(--fxs-chrome-warm); }
  100% { color: inherit; }
}
@container (inline-size < 330px) {
  .fxs-chrome .fxs-chrome__stats div:nth-child(2) { display: none; }
}
@container (inline-size < 270px) {
  .fxs-chrome .fxs-chrome__drip span { display: none; }
  .fxs-chrome .fxs-chrome__drip { padding: 8px; }
}
@media (prefers-reduced-motion: reduce) {
  .fxs-chrome {
    & .fxs-chrome__fallback i,
    & .fxs-chrome__fallback i.is-drip { animation: none; }
    & .fxs-chrome__count.is-up { animation: none; }
    & .fxs-chrome__stats div,
    & .fxs-chrome__head,
    & .fxs-chrome__drip { transition: opacity .2s linear; }
    & .fxs-chrome__drip svg { transition: none; }
  }
}

