}
const mat2 OCT = mat2(.8, .6, -.6, .8);
float fbm(vec2 p) {
  float a = .5, s = 0.;
  for (int i = 0; i < 5; i++) { s += a * vnoise(p); p = OCT * p * 2.03; a *= .5; }
  return s;
}

uniform vec3 uBg, uMetal, uLight, uWarm;
uniform vec4 uRip[10];   /* xy origin, z birth time, w amplitude */
uniform vec2 uPull, uTilt;
uniform float uPullAmt;

/* Silhouette radius by direction: a slow wobble, plus a lobe reaching for the pointer. */
float radiusAt(vec2 d, vec2 c) {
  float a = atan(d.y, d.x);
  float R = .33 + .016 * sin(a * 3. + uTime * .7) + .011 * sin(a * 5. - uTime * 1.1) + .009 * sin(a * 2. + uTime * .4);
  vec2 pd = uPull - c;
  float lp = length(pd);
  if (lp > 1e-3) {
    float al = dot(d / max(length(d), 1e-4), pd / lp);
    R += uPullAmt * .1 * pow(max(al, 0.), 7.) * smoothstep(.95, .3, lp);
  }
