}
/* x: height · y: r/R (0 centre, 1 rim) */
vec2 surface(vec2 p) {
  vec2 c = uTilt * .07;
  vec2 d = p - c;
  float r = length(d) / radiusAt(d, c);
  float dome = .2 * sqrt(max(0., 1. - pow(min(r, 1.), 4.)));   /* surface tension: flat top, steep rim */
  float rip = 0.;
  for (int i = 0; i < 10; i++) {
