vec3 env(vec3 d) {
  vec3 c = uBg * mix(.35, 1.2, smoothstep(-1., 1., d.y));
  vec2 q = d.xy - vec2(-.08, .1);
  float box = smoothstep(.07, 0., max(abs(q.x) - .36, abs(q.y) - .24));
  c += uLight * box * (1.25 + .7 * smoothstep(.24, -.24, q.y));
  c *= 1. - .82 * box * smoothstep(.014, 0., abs(q.y + .03) - .008);
  c *= 1. - .6 * box * smoothstep(.014, 0., abs(q.x - .1) - .006);
  float strip = smoothstep(.03, 0., abs(d.x + .64) - .03) * smoothstep(.2, 0., abs(d.y) - .42);
  c += uLight * strip * 2.;
  float strip2 = smoothstep(.04, 0., abs(d.x - .72) - .025) * smoothstep(.2, 0., abs(d.y - .1) - .3);
  c += uLight * strip2 * 1.1;
  float graze = 1. - max(d.z, 0.);
