void main() {
  vec2 p = (gl_FragCoord.xy - .5 * uRes) / uRes.y;
  float e = 1. / uRes.y;
  vec2 s0 = surface(p);
  float hx = surface(p + vec2(e, 0.)).x, hy = surface(p + vec2(0., e)).x;
  vec3 n = normalize(vec3(-(hx - s0.x) / e, -(hy - s0.x) / e, 1.));
