  float mask = 1. - smoothstep(1. - px, 1. + px, r);
  vec3 col = mix(table, metal, mask);
  col = col / (1. + .22 * col);
  col += (hash12(gl_FragCoord.xy) - .5) / 255.;
  gl_FragColor = vec4(col, 1.);
}
