kick();

css:
.fxs-cells {
  --fxs-cells-bg: oklch(0.15 0.02 172);
  --fxs-cells-tissue: oklch(0.31 0.045 168);
  --fxs-cells-membrane: oklch(0.86 0.1 152);
  --fxs-cells-signal: oklch(0.84 0.15 78);

  --fxs-cells-text: color-mix(in oklch, var(--fxs-cells-membrane) 30%, oklch(0.97 0.01 150));
  --fxs-cells-muted: color-mix(in oklch, var(--fxs-cells-text) 55%, var(--fxs-cells-bg));
  --fxs-cells-chip: color-mix(in oklch, var(--fxs-cells-bg) 72%, transparent);
  --fxs-cells-rule: color-mix(in oklch, var(--fxs-cells-membrane) 18%, transparent);
  --fxs-cells-out: cubic-bezier(.16, 1, .3, 1);
  --fxs-cells-spring: linear(0, 0.051, 0.174, 0.326, 0.495, 0.655, 0.795, 0.903, 0.989, 1.047, 1.082, 1.097, 1.099, 1.091, 1.077, 1.062, 1.045, 1.030, 1.017, 1.007, 0.999, 0.994, 0.991, 0.990, 0.990, 0.991, 0.993, 0.994, 0.996, 0.998, 0.999, 1.000, 1.000, 1.001, 1.001, 1.001, 1);

  container-type: inline-size;
  position: relative;
  inline-size: 100%;
  aspect-ratio: 5 / 4;
  min-block-size: 200px;
  max-block-size: 380px;
  border-radius: 16px;
  overflow: hidden;
  isolation: isolate;
  background: var(--fxs-cells-bg);
  color: var(--fxs-cells-text);
  font-family: system-ui, sans-serif;

  & .fxs-cells__gl,
  & .fxs-cells__fallback,
  & .fxs-cells__surface { position: absolute; inset: 0; inline-size: 100%; block-size: 100%; }
  & .fxs-cells__gl { display: block; }
  & .fxs-cells__surface { z-index: 1; cursor: cell; touch-action: pan-y; border-radius: inherit; outline: none; }
  & .fxs-cells__surface:focus-visible {
    box-shadow: inset 0 0 0 2px var(--fxs-cells-signal), inset 0 0 0 5px color-mix(in oklch, var(--fxs-cells-signal) 22%, transparent);
  }
  /* Floating readout pinned to a nucleus; positioned with translate from JS. */
  & .fxs-cells__tip {
    position: absolute;
    z-index: 3;
    left: 0;
    top: 0;
    display: grid;
    gap: 2px;
    padding: 5px 7px;
    border-radius: 7px;
    background: color-mix(in oklch, var(--fxs-cells-bg) 82%, transparent);
    box-shadow: inset 0 0 0 1px var(--fxs-cells-rule), 0 6px 18px -8px #000c;
    font: 500 10px/1.15 ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
    pointer-events: none;
    translate: calc(var(--x, 0) * 1px + 12px) calc(var(--y, 0) * 1px - 50%);
    opacity: 0;
    scale: .9;
    transform-origin: 0 50%;
    transition: opacity .2s var(--fxs-cells-out), scale .35s var(--fxs-cells-spring);
    & b { color: var(--fxs-cells-membrane); font-weight: 650; letter-spacing: .04em; }
    & span { color: var(--fxs-cells-muted); }
    & i { font-style: normal; color: var(--fxs-cells-signal); font-weight: 650; }
  }
  & .fxs-cells__tip[data-on] { opacity: 1; scale: 1; }
  & .fxs-cells__tip[data-flip] { translate: calc(var(--x, 0) * 1px - 100% - 12px) calc(var(--y, 0) * 1px - 50%); transform-origin: 100% 50%; }
  & .fxs-cells__ui {
    position: absolute;
    inset: 0;
    z-index: 2;
    display: grid;
    grid-template-columns: 1fr auto;
    grid-template-rows: auto 1fr auto;
    grid-template-areas: "head channel" ". ." "scale stats";
    align-items: end;
    gap: 8px;
    padding: clamp(10px, 4cqi, 18px);
    pointer-events: none;
  }
  & .fxs-cells__head { grid-area: head; align-self: start; display: grid; gap: 3px; }
  & .fxs-cells__eyebrow {
    font: 600 clamp(9px, 2.4cqi, 10.5px)/1.2 ui-monospace, Menlo, monospace;
    letter-spacing: .14em;
    text-transform: uppercase;
    color: var(--fxs-cells-muted);
    text-shadow: 0 0 6px var(--fxs-cells-bg), 0 0 2px var(--fxs-cells-bg);
  }
  & .fxs-cells__title {
    margin: 0;
    font-size: clamp(19px, 7cqi, 28px);
    font-weight: 650;
    letter-spacing: -.03em;
    line-height: 1;
    text-wrap: balance;
    text-shadow: 0 1px 12px var(--fxs-cells-bg);
  }
  & .fxs-cells__channel {
    grid-area: channel;
    align-self: start;
    justify-self: end;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 5px 8px;
    border-radius: 99px;
    background: var(--fxs-cells-chip);
    box-shadow: inset 0 0 0 1px var(--fxs-cells-rule);
    font: 600 10px/1 ui-monospace, Menlo, monospace;
    letter-spacing: .06em;
    &::before {
      content: "";
      inline-size: 7px;
      aspect-ratio: 1;
      border-radius: 50%;
      background: var(--fxs-cells-signal);
      box-shadow: 0 0 8px var(--fxs-cells-signal);
      animation: fxs-cells-blink 2.4s var(--fxs-cells-out) infinite;
    }
  }
  & .fxs-cells__scale {
    grid-area: scale;
    justify-self: start;
    display: grid;
    gap: 4px;
    font: 600 10px/1 ui-monospace, Menlo, monospace;
    & i {
      display: block;
      inline-size: calc(var(--bar, 64) * 1px);
      block-size: 3px;
      border-radius: 2px;
      background: var(--fxs-cells-text);
      box-shadow: 0 0 0 1px color-mix(in oklch, var(--fxs-cells-bg) 60%, transparent);
    }
  }
  & .fxs-cells__stats {
    grid-area: stats;
    display: flex;
    gap: 10px;
    padding: 6px 9px;
    border-radius: 9px;
    background: var(--fxs-cells-chip);
    box-shadow: inset 0 0 0 1px var(--fxs-cells-rule);
    font: 500 10.5px/1 ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
    color: var(--fxs-cells-muted);
    white-space: nowrap;
    & b { color: var(--fxs-cells-text); font-weight: 650; display: inline-block; }
    & b.is-up { animation: fxs-cells-up .6s var(--fxs-cells-spring); }
  }
  & .fxs-cells__head,
  & .fxs-cells__channel,
  & .fxs-cells__scale,
  & .fxs-cells__stats {
    transition: opacity .7s var(--fxs-cells-out) .12s, translate .8s var(--fxs-cells-out) .12s;
    @starting-style { opacity: 0; translate: 0 6px; }
  }
  & .fxs-cells__sr { position: absolute; inline-size: 1px; block-size: 1px; overflow: hidden;
    clip-path: inset(50%); white-space: nowrap; }

  /* No WebGL: a hex-ish lattice of cells with a radial wave sweeping through. */
  & .fxs-cells__fallback {
    display: none;
    background:
      radial-gradient(circle, color-mix(in oklch, var(--fxs-cells-signal) 70%, transparent) 0 4px, transparent 5px) 0 0 / 46px 40px,
      radial-gradient(circle, transparent 0 18px, color-mix(in oklch, var(--fxs-cells-membrane) 45%, transparent) 19px 20px, transparent 21px) 0 0 / 46px 40px,
      radial-gradient(circle, transparent 0 18px, color-mix(in oklch, var(--fxs-cells-membrane) 45%, transparent) 19px 20px, transparent 21px) 23px 20px / 46px 40px,
      var(--fxs-cells-tissue);
    &::after {
      content: "";
      position: absolute;
      inset: 0;
      background: radial-gradient(circle at 40% 55%, transparent 0 20%, color-mix(in oklch, var(--fxs-cells-signal) 40%, transparent) 26%, transparent 34%);
      animation: fxs-cells-sweep 4s var(--fxs-cells-out) infinite;
    }
  }
