  &[data-render="fallback"] .fxs-cells__gl,
  &[data-render="fallback"] .fxs-cells__stats,
  &[data-render="fallback"] .fxs-cells__tip { display: none; }
}
@keyframes fxs-cells-blink {
  0%, 100% { opacity: 1; }
  50% { opacity: .35; }
}
@keyframes fxs-cells-up {
  0% { translate: 0 0; color: var(--fxs-cells-signal); }
  30% { translate: 0 -4px; }
  100% { translate: 0 0; }
}
@keyframes fxs-cells-sweep {
  from { scale: .3; opacity: 1; }
  to { scale: 2.4; opacity: 0; }
}
@container (inline-size < 300px) {
  .fxs-cells .fxs-cells__channel { display: none; }
  .fxs-cells .fxs-cells__stats span:last-child { display: none; }
}
@media (prefers-reduced-motion: reduce) {
  .fxs-cells {
    & .fxs-cells__channel::before,
    & .fxs-cells__fallback::after,
    & .fxs-cells__stats b.is-up { animation: none; }
    & .fxs-cells__tip { transition: opacity .15s linear; }
    & .fxs-cells__head,
    & .fxs-cells__channel,
    & .fxs-cells__scale,
    & .fxs-cells__stats { transition: opacity .2s linear; }
  }
}

