kick();

css:
@property --fxs-sky-drift {
  syntax: '<percentage>';
  inherits: false;
  initial-value: 0%;
}
.fxs-sky {
  --fxs-sky-day: oklch(0.66 0.11 238);
  --fxs-sky-glow: oklch(0.82 0.12 62);
  --fxs-sky-dusk: oklch(0.36 0.09 292);
  --fxs-sky-land: oklch(0.27 0.035 175);

  --fxs-sky-text: oklch(0.99 0.006 90);
  --fxs-sky-muted: color-mix(in oklch, var(--fxs-sky-text) 72%, transparent);
  --fxs-sky-chip: color-mix(in oklch, var(--fxs-sky-land) 46%, transparent);
  --fxs-sky-rule: color-mix(in oklch, var(--fxs-sky-text) 22%, transparent);
  --fxs-sky-out: cubic-bezier(.16, 1, .3, 1);
  --fxs-sky-spring: linear(0, 0.050, 0.161, 0.309, 0.465, 0.607, 0.735, 0.837, 0.920, 0.979, 1.017, 1.041, 1.053, 1.056, 1.052, 1.046, 1.038, 1.029, 1.021, 1.014, 1.008, 1.004, 1.001, 0.999, 0.998, 0.997, 0.997, 0.997, 0.997, 0.998, 0.998, 0.999, 0.999, 1.000, 1.000, 1.000, 1);

  container-type: inline-size;
  position: relative;
  inline-size: 100%;
  aspect-ratio: 5 / 4;
  min-block-size: 200px;
  max-block-size: 380px;
  border-radius: 16px;
  overflow: hidden;
  isolation: isolate;
  background: var(--fxs-sky-day);
  color: var(--fxs-sky-text);
  font-family: system-ui, sans-serif;

  & .fxs-sky__gl,
  & .fxs-sky__fallback,
  & .fxs-sky__surface { position: absolute; inset: 0; inline-size: 100%; block-size: 100%; }
  & .fxs-sky__gl { display: block; }
  & .fxs-sky__surface { z-index: 1; }
  & .fxs-sky__ui {
    position: absolute;
    inset: 0;
    z-index: 2;
    display: grid;
    grid-template-columns: 1fr auto;
    grid-template-rows: auto 1fr auto;
    grid-template-areas: "head facts" ". ." "control control";
    gap: 8px;
    padding: clamp(10px, 4cqi, 18px);
    pointer-events: none;
    text-shadow: 0 1px 10px color-mix(in oklch, var(--fxs-sky-land) 55%, transparent);
  }
  & .fxs-sky__head { grid-area: head; display: grid; gap: 2px; align-content: start; }
  & .fxs-sky__eyebrow {
    font: 600 clamp(9px, 2.4cqi, 10.5px)/1.2 ui-monospace, Menlo, monospace;
    letter-spacing: .14em;
    text-transform: uppercase;
    color: var(--fxs-sky-muted);
  }
  & .fxs-sky__clock {
    font-size: clamp(30px, 13cqi, 52px);
    font-weight: 200;
    letter-spacing: -.045em;
    line-height: .92;
    font-variant-numeric: tabular-nums;
  }
  & .fxs-sky__facts {
    grid-area: facts;
    display: grid;
    gap: 6px;
    align-content: start;
    justify-items: end;
    margin: 0;
    & div { display: grid; justify-items: end; gap: 2px; }
    & dt { font: 600 9px/1 ui-monospace, Menlo, monospace; letter-spacing: .14em; text-transform: uppercase; color: var(--fxs-sky-muted); }
    & dd { margin: 0; font-size: 12.5px; font-weight: 600; font-variant-numeric: tabular-nums; white-space: nowrap; }
  }
  & .fxs-sky__phase { transition: opacity .3s; }
  & .fxs-sky__phase.is-swap { animation: fxs-sky-swap .5s var(--fxs-sky-out); }
  & .fxs-sky__control {
    grid-area: control;
    pointer-events: auto;
    display: grid;
    gap: 5px;
    padding: 9px 12px 7px;
    border-radius: 14px;
    background: var(--fxs-sky-chip);
    box-shadow: inset 0 0 0 1px var(--fxs-sky-rule);
    backdrop-filter: blur(12px) saturate(1.3);
    text-shadow: none;
  }
  & .fxs-sky__head,
  & .fxs-sky__facts,
  & .fxs-sky__control {
    transition: opacity .7s var(--fxs-sky-out) .12s, translate .8s var(--fxs-sky-out) .12s;
    @starting-style { opacity: 0; translate: 0 8px; }
  }
  & .fxs-sky__range {
    appearance: none;
    inline-size: 100%;
    block-size: 18px;
    margin: 0;
    background: transparent;
    accent-color: var(--fxs-sky-glow);
    cursor: pointer;
    &::-webkit-slider-runnable-track {
      block-size: 4px;
      border-radius: 4px;
      background: linear-gradient(90deg, var(--fxs-sky-dusk), var(--fxs-sky-glow) 8%, var(--fxs-sky-day) 30% 70%, var(--fxs-sky-glow) 92%, var(--fxs-sky-dusk));
    }
    &::-moz-range-track {
      block-size: 4px;
      border-radius: 4px;
      background: linear-gradient(90deg, var(--fxs-sky-dusk), var(--fxs-sky-glow) 8%, var(--fxs-sky-day) 30% 70%, var(--fxs-sky-glow) 92%, var(--fxs-sky-dusk));
    }
    &::-webkit-slider-thumb {
      appearance: none;
      inline-size: 18px;
      block-size: 18px;
      margin-block-start: -7px;
      border-radius: 50%;
      background: radial-gradient(circle, var(--fxs-sky-text) 0 4px, var(--fxs-sky-glow) 5px);
      box-shadow: 0 0 0 3px color-mix(in oklch, var(--fxs-sky-text) 85%, transparent), 0 0 16px var(--fxs-sky-glow);
      transition: scale .4s var(--fxs-sky-spring);
    }
    &::-moz-range-thumb {
      inline-size: 18px; block-size: 18px; border: 0; border-radius: 50%;
      background: var(--fxs-sky-glow);
      box-shadow: 0 0 0 3px var(--fxs-sky-text);
    }
    &:active::-webkit-slider-thumb { scale: 1.2; }
    &:focus-visible { outline: 2px solid var(--fxs-sky-text); outline-offset: 4px; border-radius: 6px; }
  }
  & .fxs-sky__ticks {
    position: relative;
    block-size: 11px;
    font: 500 9.5px/1 ui-monospace, Menlo, monospace;
    color: var(--fxs-sky-muted);
    font-variant-numeric: tabular-nums;
    & i {
      position: absolute;
      left: calc(9px + var(--at) * (100% - 18px));
      translate: -50% 0;
      font-style: normal;
      white-space: nowrap;
    }
    & i:first-child { translate: -9px 0; }
    & i:last-child { translate: calc(-100% + 9px) 0; }
    & small { font-size: inherit; opacity: .7; }
  }
  & .fxs-sky__sr { position: absolute; inline-size: 1px; block-size: 1px; overflow: hidden;
    clip-path: inset(50%); white-space: nowrap; }

  /* No WebGL: a CSS sky with a sun and two drifting cloud banks. */
  & .fxs-sky__fallback {
    display: none;
    background: linear-gradient(to top, var(--fxs-sky-glow), var(--fxs-sky-day) 70%);
    & i {
      position: absolute;
      inline-size: 12%;
      aspect-ratio: 1;
      left: calc(4% + var(--sun-x, .12) * 84%);
      top: calc(64% - var(--sun-y, .21) * 54%);
      transition: left .6s var(--fxs-sky-out), top .6s var(--fxs-sky-out);
      border-radius: 50%;
      background: oklch(0.99 0.03 90);
      box-shadow: 0 0 40px 18px color-mix(in oklch, var(--fxs-sky-glow) 70%, transparent);
    }
    & b {
      position: absolute;
      inset: calc(16% + var(--i) * 22%) -30% auto;
      block-size: 22%;
      border-radius: 50%;
      background: radial-gradient(closest-side, oklch(0.98 0.01 90 / .9), transparent);
      filter: blur(6px);
      translate: var(--fxs-sky-drift) 0;
      animation: fxs-sky-drift calc(30s + var(--i) * 12s) linear infinite alternate;
    }
    &::after {
      content: "";
      position: absolute;
      inset: 72% 0 0;
      background: var(--fxs-sky-land);
      clip-path: polygon(0 30%, 18% 12%, 34% 26%, 52% 4%, 70% 22%, 86% 10%, 100% 24%, 100% 100%, 0 100%);
    }
  }
  &[data-render="fallback"] .fxs-sky__fallback { display: block; }
  &[data-render="fallback"] .fxs-sky__gl { display: none; }
}
@keyframes fxs-sky-drift {
  from { --fxs-sky-drift: -12%; }
  to { --fxs-sky-drift: 14%; }
}
@keyframes fxs-sky-swap {
  from { opacity: 0; translate: 0 4px; }
  to { opacity: 1; translate: 0 0; }
}
@container (inline-size < 300px) {
  .fxs-sky .fxs-sky__ticks small { display: none; }
  .fxs-sky .fxs-sky__ticks i:nth-child(2) { display: none; }
}
@media (prefers-reduced-motion: reduce) {
  .fxs-sky {
    & .fxs-sky__fallback b,
    & .fxs-sky__phase.is-swap { animation: none; }
    & .fxs-sky__head,
    & .fxs-sky__facts,
    & .fxs-sky__control { transition: opacity .2s linear; }
  }
}

