const FRAG = `#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif
uniform vec2 uRes;
uniform float uTime;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * .1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}
float vnoise(vec2 p) {
  vec2 i = floor(p), f = fract(p);
  vec2 w = f * f * (3. - 2. * f);
  return mix(mix(hash12(i), hash12(i + vec2(1., 0.)), w.x),
             mix(hash12(i + vec2(0., 1.)), hash12(i + vec2(1., 1.)), w.x), w.y);
}
const mat2 OCT = mat2(.8, .6, -.6, .8);
float fbm(vec2 p) {
  float a = .5, s = 0.;
  for (int i = 0; i < 5; i++) { s += a * vnoise(p); p = OCT * p * 2.03; a *= .5; }
  return s;
}

uniform vec3 uZenith, uHorizon, uSun, uLit, uShade, uLand, uHaze;
uniform vec2 uSunPos, uLook;
uniform float uNight;

float density(vec2 q) {
  vec2 w = vec2(fbm(q * .55 + vec2(0., uTime * .012)), fbm(q * .55 + vec2(3.1, 1.7)));
  float f = fbm(q + w * 1.3 + vec2(uTime * .035, 0.));
  f += .1 * (vnoise(q * 6. + vec2(uTime * .06, 0.)) - .5);     /* erode the edges */
  return smoothstep(.46, .7, f);
}
/* i = 0 nearest (low, rolling), i = 2 farthest (sits on the horizon, flatter). */
float hill(float x, float i) {
  return -.07 + i * .055 + (.11 - i * .03) * (fbm(vec2(x * (1.6 - i * .35) + i * 7.3, i * 3.1)) - .3);
}
void main() {
  vec2 p = (gl_FragCoord.xy - .5 * uRes) / uRes.y;
  float hz = -.2 - uLook.y * .035;
  float y = p.y - hz;
  float dSun = length(p - uSunPos);

  vec3 col = mix(uHorizon, uZenith, pow(smoothstep(0., .72, y), .65));
  col += uSun * (exp(-dSun * 7.) * .32 + exp(-dSun * 26.) * .45) * (1. - uNight * .9);
  if (uNight > 0.) {
    vec2 sp = p * 110.;
    vec2 id = floor(sp);
    float hs = hash12(id);
    vec2 f = fract(sp) - .5;
    col += vec3(.9, .92, 1.) * step(.975, hs) * smoothstep(.16, 0., length(f)) * uNight * (.5 + .5 * sin(uTime * 2. + hs * 50.));
  }
  col = mix(col, uSun * 1.25 + .15, (1. - smoothstep(.028, .034, dSun)) * (1. - uNight));

  if (y > 0.) {
    /* Project onto a cloud deck: rows near the horizon are far away and compressed. */
    float z = .32 / (y + .02);
    vec2 q = vec2((p.x + uLook.x * .25) * z, z + uTime * .05) * 1.5;
    float d = density(q);
    vec2 toSun = normalize(vec2(uSunPos.x - p.x, max(uSunPos.y - p.y, -.2) + .35));
    float d2 = density(q + toSun * .16);
    float light = clamp(.55 + (d - d2) * 2.4, 0., 1.);
    vec3 cloud = mix(uShade, uLit, light * .8 + .2 * (1. - d));
    cloud += uSun * pow(1. - d, 3.) * exp(-dSun * 4.) * .9 * (1. - uNight);   /* silver lining */
    float fade = smoothstep(0., .22, y);
    col = mix(col, mix(uHaze, cloud, fade), d * mix(.35, .95, fade));
  }
  /* Three ridges, far to near: hazier with distance, more parallax up close. */
  for (int k = 2; k >= 0; k--) {
    float i = float(k);
    float top = hz + hill(p.x + uLook.x * (.04 + (2. - i) * .07), i);
    float m = smoothstep(top + .002, top - .002, p.y);
    vec3 lc = mix(uLand, uHaze, i * .32 + .08);
    lc = mix(lc, uSun, .06 * (1. - uNight) * smoothstep(top - .04, top, p.y));
    col = mix(col, lc * (.92 + .08 * smoothstep(top - .2, top, p.y)), m);
  }
  col += (hash12(gl_FragCoord.xy) - .5) / 255.;
  gl_FragColor = vec4(col, 1.);
}
`;
const T0 = 40;
