  P = [
    { alt: -9, zen: mul(dusk, .22), hor: mul(dusk, .42), sun: mul(glow, .2), lit: mul(dusk, .5), shade: mul(dusk, .24), haze: mul(dusk, .4), night: 1 },
    { alt: -2.5, zen: mul(dusk, .75), hor: mix(dusk, glow, .5), sun: glow, lit: mix(glow, dusk, .35), shade: mul(dusk, .62), haze: mix(dusk, glow, .3), night: .35 },
    { alt: 3, zen: mix(dusk, day, .4), hor: glow, sun: mix(glow, WHITE, .25), lit: mix(glow, WHITE, .3), shade: mix(dusk, glow, .3), haze: mix(glow, dusk, .2), night: 0 },
    { alt: 14, zen: mix(day, dusk, .18), hor: mix(glow, WHITE, .45), sun: mix(glow, WHITE, .55), lit: mix(WHITE, glow, .3), shade: mix(mul(day, .7), glow, .25), haze: mix(glow, WHITE, .4), night: 0 },
    { alt: 40, zen: day, hor: mix(day, WHITE, .62), sun: WHITE, lit: WHITE, shade: mix(day, WHITE, .5), haze: mix(day, WHITE, .55), night: 0 },
