  return 'Daylight';
}
function fmt(hr) {
  const m = Math.round(hr * 60);
  return String(Math.floor(m / 60)).padStart(2, '0') + ':' + String(m % 60).padStart(2, '0');
}
function readout(hr, announce) {
  const alt = altitude(hr), ph = phaseOf(hr, alt), c = fmt(hr);
  if (c !== shownClock) { shownClock = c; clockEl.textContent = c; clockEl.dateTime = c; altEl.textContent = alt.toFixed(1) + '°'; }
  if (ph !== shownPhase) {
    shownPhase = ph;
    phaseEl.textContent = ph;
    phaseEl.classList.remove('is-swap'); void phaseEl.offsetWidth; phaseEl.classList.add('is-swap');
