  kick();
}
range.addEventListener('input', () => syncRange(false));
range.addEventListener('change', () => syncRange(true));

theme();
readout(hour, false);
syncRange(false);
kick();

css:
@property --fxs-lens-spin {
  syntax: '<angle>';
  inherits: false;
  initial-value: 0deg;
}
.fxs-lens {
  --fxs-lens-void: oklch(0.11 0.012 50);
  --fxs-lens-disk: oklch(0.88 0.13 78);
  --fxs-lens-dust: oklch(0.48 0.12 30);
  --fxs-lens-star: oklch(0.97 0.02 90);

  --fxs-lens-text: color-mix(in oklch, var(--fxs-lens-star) 94%, var(--fxs-lens-disk));
  --fxs-lens-muted: color-mix(in oklch, var(--fxs-lens-star) 50%, var(--fxs-lens-void));
  --fxs-lens-chip: color-mix(in oklch, var(--fxs-lens-void) 70%, transparent);
  --fxs-lens-rule: color-mix(in oklch, var(--fxs-lens-star) 12%, transparent);
  --fxs-lens-track: color-mix(in oklch, var(--fxs-lens-star) 16%, var(--fxs-lens-void));
  --fxs-lens-out: cubic-bezier(.16, 1, .3, 1);
  --fxs-lens-spring: linear(0, 0.059, 0.197, 0.366, 0.548, 0.716, 0.855, 0.959, 1.034, 1.080, 1.101, 1.104, 1.096, 1.080, 1.061, 1.042, 1.026, 1.012, 1.002, 0.995, 0.991, 0.989, 0.989, 0.990, 0.992, 0.994, 0.996, 0.998, 0.999, 1.000, 1.001, 1.001, 1.001, 1.001, 1.001, 1.001, 1);

  container-type: inline-size;
  position: relative;
  inline-size: 100%;
  aspect-ratio: 5 / 4;
  min-block-size: 200px;
  max-block-size: 380px;
  border-radius: 16px;
  overflow: hidden;
  isolation: isolate;
  background: var(--fxs-lens-void);
  color: var(--fxs-lens-text);
  font-family: system-ui, sans-serif;

  & .fxs-lens__gl,
  & .fxs-lens__fallback,
  & .fxs-lens__surface { position: absolute; inset: 0; inline-size: 100%; block-size: 100%; }
  & .fxs-lens__gl { display: block; }
  & .fxs-lens__surface { z-index: 1; cursor: none; touch-action: none; border-radius: inherit; outline: none; }
  & .fxs-lens__surface:focus-visible {
    box-shadow: inset 0 0 0 2px var(--fxs-lens-disk), inset 0 0 0 5px color-mix(in oklch, var(--fxs-lens-disk) 22%, transparent);
  }
  & .fxs-lens__ui {
    position: absolute;
    inset: 0;
    z-index: 2;
    display: grid;
    grid-template-columns: 1fr auto;
    grid-template-rows: auto 1fr auto;
    grid-template-areas: "head facts" ". ." "control control";
    gap: 8px;
    padding: clamp(10px, 4cqi, 18px);
    pointer-events: none;
  }
  & .fxs-lens__head { grid-area: head; display: grid; gap: 3px; align-content: start; }
  & .fxs-lens__eyebrow {
    font: 600 clamp(9px, 2.4cqi, 10.5px)/1.2 ui-monospace, Menlo, monospace;
    letter-spacing: .14em;
    text-transform: uppercase;
    color: var(--fxs-lens-muted);
  }
  & .fxs-lens__title {
    margin: 0;
    font-size: clamp(18px, 6.6cqi, 27px);
    font-weight: 600;
    letter-spacing: -.035em;
    line-height: 1;
    text-wrap: balance;
  }
  & .fxs-lens__facts {
    grid-area: facts;
    display: grid;
    grid-template-columns: auto auto;
    gap: 4px 8px;
    align-content: start;
    margin: 0;
    font: 500 11px/1 ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
    & div { display: contents; }
    & dt { color: var(--fxs-lens-muted); font-style: italic; text-align: end; }
    & dd { margin: 0; color: var(--fxs-lens-text); text-align: end; min-inline-size: 8ch; }
    & sub { font-size: .75em; font-style: normal; }
  }
  & .fxs-lens__control {
    grid-area: control;
    pointer-events: auto;
    display: grid;
    grid-template-columns: auto 1fr auto;
    align-items: center;
    gap: 10px;
    padding: 8px 12px;
    border-radius: 13px;
    background: var(--fxs-lens-chip);
    box-shadow: inset 0 0 0 1px var(--fxs-lens-rule);
    backdrop-filter: blur(10px);
  }
  & .fxs-lens__head,
  & .fxs-lens__facts,
  & .fxs-lens__control {
    transition: opacity .8s var(--fxs-lens-out) .15s, translate .9s var(--fxs-lens-out) .15s, filter .9s var(--fxs-lens-out) .15s;
    @starting-style { opacity: 0; translate: 0 6px; filter: blur(4px); }
  }
  & .fxs-lens__label { font-size: 12px; font-weight: 600; }
  & .fxs-lens__range {
    appearance: none;
    inline-size: 100%;
    block-size: 18px;
    margin: 0;
    background: transparent;
    accent-color: var(--fxs-lens-disk);
    cursor: pointer;
    &::-webkit-slider-runnable-track {
      block-size: 3px;
      border-radius: 3px;
      background: linear-gradient(90deg, var(--fxs-lens-dust), var(--fxs-lens-disk));
    }
    &::-moz-range-track { block-size: 3px; border-radius: 3px; background: linear-gradient(90deg, var(--fxs-lens-dust), var(--fxs-lens-disk)); }
    &::-webkit-slider-thumb {
      appearance: none;
      inline-size: 16px;
      block-size: 16px;
      margin-block-start: -6.5px;
      border-radius: 50%;
      background: var(--fxs-lens-void);
      box-shadow: 0 0 0 2px var(--fxs-lens-disk), 0 0 14px color-mix(in oklch, var(--fxs-lens-disk) 70%, transparent);
      transition: scale .4s var(--fxs-lens-spring);
    }
    &::-moz-range-thumb {
      inline-size: 16px; block-size: 16px; border: 0; border-radius: 50%;
      background: var(--fxs-lens-void);
      box-shadow: 0 0 0 2px var(--fxs-lens-disk);
    }
    &:active::-webkit-slider-thumb { scale: 1.25; }
    &:focus-visible { outline: 2px solid var(--fxs-lens-disk); outline-offset: 4px; border-radius: 6px; }
  }
  & .fxs-lens__mass {
    font: 500 11.5px/1 ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
    color: var(--fxs-lens-muted);
    white-space: nowrap;
    & b { display: inline-block; min-inline-size: 3ch; text-align: end; color: var(--fxs-lens-text); font-weight: 650; }
    & sup, & sub { font-size: .72em; }
  }
  & .fxs-lens__sr { position: absolute; inline-size: 1px; block-size: 1px; overflow: hidden;
    clip-path: inset(50%); white-space: nowrap; }

  /* No WebGL: a flattened conic ring around a dark disc, turning. */
  & .fxs-lens__fallback {
    display: none;
    place-items: center;
    background: radial-gradient(circle at 50% 50%, color-mix(in oklch, var(--fxs-lens-dust) 35%, transparent), transparent 60%), var(--fxs-lens-void);
    & i {
      position: relative;
      inline-size: 22%;
      aspect-ratio: 1;
      border-radius: 50%;
      background: #000;
      scale: var(--m, 1);
      transition: scale .5s var(--fxs-lens-spring);
      box-shadow: 0 0 0 3px var(--fxs-lens-disk), 0 0 30px 6px color-mix(in oklch, var(--fxs-lens-disk) 50%, transparent);
      &::before {
        content: "";
        position: absolute;
        inset: 30% -110%;
        z-index: -1;
        border-radius: 50%;
        background: conic-gradient(from var(--fxs-lens-spin), var(--fxs-lens-disk), var(--fxs-lens-dust), var(--fxs-lens-disk), var(--fxs-lens-dust), var(--fxs-lens-disk));
        mask: radial-gradient(closest-side, transparent 38%, #000 42% 90%, transparent);
        animation: fxs-lens-spin 9s linear infinite;
      }
    }
  }
  &[data-render="fallback"] .fxs-lens__fallback { display: grid; }
  &[data-render="fallback"] .fxs-lens__gl { display: none; }
}
@keyframes fxs-lens-spin {
  to { --fxs-lens-spin: 360deg; }
}
@container (inline-size < 300px) {
  .fxs-lens .fxs-lens__facts div:last-child { display: none; }
  .fxs-lens .fxs-lens__label,
  .fxs-lens .fxs-lens__sim { display: none; }
}
@media (prefers-reduced-motion: reduce) {
  .fxs-lens {
    & .fxs-lens__fallback i::before { animation: none; }
    & .fxs-lens__head,
    & .fxs-lens__facts,
    & .fxs-lens__control { transition: opacity .2s linear; }
  }
}

