const FRAG = `#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif
uniform vec2 uRes;
uniform float uTime;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * .1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}
float vnoise(vec2 p) {
  vec2 i = floor(p), f = fract(p);
  vec2 w = f * f * (3. - 2. * f);
  return mix(mix(hash12(i), hash12(i + vec2(1., 0.)), w.x),
             mix(hash12(i + vec2(0., 1.)), hash12(i + vec2(1., 1.)), w.x), w.y);
}
const mat2 OCT = mat2(.8, .6, -.6, .8);
float fbm(vec2 p) {
  float a = .5, s = 0.;
  for (int i = 0; i < 5; i++) { s += a * vnoise(p); p = OCT * p * 2.03; a *= .5; }
  return s;
}

uniform vec3 uVoid, uDisk, uDust, uStar;
uniform vec2 uC, uGal;   /* hole centre, background galaxy position */
uniform float uTE;       /* Einstein radius, units of height */

mat2 rot(float a) { float c = cos(a), s = sin(a); return mat2(c, s, -s, c); }

vec3 starfield(vec2 q) {
  vec3 c = vec3(0.);
  for (int L = 0; L < 3; L++) {
    float s = 40. + float(L) * 36.;
    vec2 g = q * s + float(L) * 17.3;
    vec2 id = floor(g), f = fract(g) - .5;
    float h = hash12(id);
    if (h > .88) {
      vec2 o = (vec2(hash12(id + 1.3), hash12(id + 5.1)) - .5) * .7;
      float b = (h - .88) / .12;
      vec3 tint = mix(vec3(1., .8, .62), vec3(.82, .9, 1.), hash12(id + 9.));
      c += tint * uStar * b * b * smoothstep(.06 + .08 * b, 0., length(f - o)) * 1.4;
    }
  }
  return c;
}
vec3 galaxy(vec2 q) {
  vec2 g = rot(.5) * (q - uGal);
  g.y *= 2.3;
  float r = length(g);
  float a = atan(g.y, g.x);
  float arms = .5 + .5 * cos(2. * a - log(r + 1e-3) * 5.5);
  return uDisk * exp(-r * 40.) * 1.5 + mix(uDust, uStar, .55) * exp(-r * 10.) * (.3 + .7 * arms) * .9;
}
vec3 background(vec2 q) {
  float n = fbm(q * 1.5 + vec2(3., 1.));
  float lanes = smoothstep(.35, .65, fbm(q * 3.4 - 2.));
  vec3 neb = uDust * pow(n, 2.6) * 1.2 * (.35 + .65 * lanes);
  return uVoid + neb + starfield(q) + galaxy(q);
}
/* Thin accretion disk seen 75° from face-on, Keplerian shear, Doppler-brightened on the approaching side. */
vec4 disk(vec2 d) {
  vec2 e = vec2(d.x, d.y / .26);
  float r = length(e) / uTE;
  float rin = 1.2, rout = 3.4;
  if (r < rin * .9 || r > rout * 1.05) return vec4(0.);
  float m = smoothstep(rin, rin + .15, r) * (1. - smoothstep(rout - 1.1, rout, r));
  vec2 k = rot(uTime * .8 / pow(r, 1.5)) * e / uTE;
  float tex = fbm(k * 2.4);
  float streak = .5 + .5 * sin(r * 20. + tex * 7.);
  float dop = 1. + .7 * (-e.x / max(length(e), 1e-4));
  float heat = pow(rin / r, 2.);
  vec3 col = mix(uDust * 1.5, uDisk, heat) * (heat * 1.9 + .2) * dop * (.45 + .75 * streak);
  return vec4(col, m * (.55 + .45 * streak));
}
void main() {
  vec2 p = (gl_FragCoord.xy - .5 * uRes) / uRes.y;
  vec2 d = p - uC;
  float r2 = dot(d, d), r = sqrt(r2);
  float te = uTE;
  /* The point-mass lens equation: where on the sky did this ray come from? */
  vec2 beta = p - te * te * d / max(r2, 1e-6);
  vec3 col = background(beta);
  vec2 bd = beta - uC;
  vec4 back = disk(bd);
  col += back.rgb * back.a * smoothstep(-.004, .004, bd.y);     /* far half, lensed over the top */
  float rs = te * .5;
  col *= smoothstep(rs * .97, rs * 1.02, r);                     /* the shadow */
  col += uDisk * exp(-abs(r - rs * 1.06) / (te * .018)) * .85;  /* photon ring */
  col += uDisk * .035 * te / max(r - rs * .9, .004) * smoothstep(rs * .9, rs * 1.1, r);
  vec4 front = disk(d);
  float fa = front.a * smoothstep(.012, -.012, d.y);
  col = col * (1. - fa * .85) + front.rgb * fa;                  /* near half, in front of everything */
  col = 1. - exp(-col * 1.25);
  col += (hash12(gl_FragCoord.xy) - .5) / 255.;
  gl_FragColor = vec4(col, 1.);
}
`;
