const GAL = [.05, .03];
const surface = root.querySelector('.fxs-lens__surface');
const range = root.querySelector('.fxs-lens__range');
const fallback = root.querySelector('.fxs-lens__fallback');
const massEl = root.querySelector('.fxs-lens__mass b');
const teEl = root.querySelector('.fxs-lens__te');
const rsEl = root.querySelector('.fxs-lens__rs');
const live = root.querySelector('.fxs-lens__sr');
const pal = {};
/* The hole is heavy: an under-damped spring, so it lags the pointer and settles. */
